/** Return value of `useDataGridServerRows` in scroll mode. */
export type UseDataGridServerRowsScrollResult<TData> = {
  /** Spread onto `<DataGrid {...server.gridProps} columns={columns} />`. */
  gridProps: UseDataGridServerRowsScrollProviderProps<TData> & UseDataGridServerRowsRootProps;
  /** The part of `gridProps` for `<DataGridProvider>` in a composed layout. */
  providerProps: UseDataGridServerRowsScrollProviderProps<TData>;
  /** The part of `gridProps` for `<DataGridRoot>` in a composed layout: the loading flag and the error state. */
  rootProps: UseDataGridServerRowsRootProps;
  /** The sort, filter, and search text of the current requests. */
  spec: ServerSpec;
  /** The row count of the result; `null` until the first block lands, and for a sequential source until it ends or the server sends one. */
  totalRowCount: number | null;
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec that no landed block has replaced, or `null`. */
  error: unknown;
  /** Repeats the blocks that failed. Does nothing without an error. */
  retry: () => void;
  /**
   * Fetches the rendered rows again and keeps them on screen until the answers land. Drops every other loaded row. A sequential
   * source refetches from the first block up to the rendered rows. A row with a pending edit, delete, or in-flight save keeps its local state.
   * The hook calls it after saves settle by `refreshAfterSave`; call it yourself with `refreshAfterSave: false` or a void `onSave`.
   */
  refresh: () => void;
  /** Asks the server to place the pushed rows again: one `refresh()` on the next frame, or after `reshapeDelayMs` when it is set. Calls in one frame join. A sequential source skips it while the rendered rows plus `overscan` end beyond 10 blocks. */
  reshape: () => void;
  /**
   * Whether a timed refresh would run now. A sequential source skips `revalidateIntervalMs`, `reshapeDelayMs`, and `refreshAfterSave`
   * refreshes while the rendered rows plus `overscan` end beyond 10 blocks, and then returns `false`; call `refresh()` yourself there.
   * Not reactive: read it in an effect or a handler.
   */
  canRevalidate: () => boolean;
  /** Rows with no data yet; they render as skeletons. A sequential source reports its one block of skeletons. */
  unloadedCount: number;
  /** The loaded ranges, merged and ascending. Not reactive: read it in an effect or a handler. */
  getLoadedRanges: () => readonly RowRange[];
  /**
   * Unloads the rows in `range` and aborts the requests it covers; the next rendered window that covers them fetches them again.
   * Rows with an open edit, a pending save, or an unsaved change, and the row under the active cell, stay in `data` but stop counting as loaded. Does nothing on a sequential source.
   */
  evict: (range: RowRange) => void;
};

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";
import { distanceToCentre, rangesIntersect } from "./fetch-hygiene";
import { subtractRanges } from "./range-math";
import type { ProtectedRows } from "./refresh-guard";
import type { Core } from "./scroll-core";
import { protectedSlotsIn } from "./scroll-eviction";

/** One landed block of a sequential chain: where its rows sit in `data` and the request that fetches it again. */
export type SeqBlock = { local: number; length: number; server: number; serverEnd: number; cursor: unknown; evicted: boolean };

/** The loaded rows of a sequential chain: `[0, position)` minus the evicted blocks. */
export function sequenceLoaded(position: number, blocks: readonly SeqBlock[]): RowRange[] {
  const gone = blocks.filter((block) => block.evicted).map((block) => ({ start: block.local, end: block.local + block.length }));
  return position > 0 ? subtractRanges({ start: 0, end: position }, gone) : [];
}

/** The evicted blocks that overlap `range`. */
export function evictedBlocksIn(blocks: readonly SeqBlock[], range: RowRange): SeqBlock[] {
  let low = 0;
  let high = blocks.length;
  while (low < high) {
    const mid = (low + high) >> 1;
    if (blocks[mid]!.local + blocks[mid]!.length <= range.start) low = mid + 1;
    else high = mid;
  }
  const found: SeqBlock[] = [];
  for (let index = low; index < blocks.length && blocks[index]!.local < range.end; index++) if (blocks[index]!.evicted) found.push(blocks[index]!);
  return found;
}

/** Moves the blocks after a local insert (`delta` 1) or delete (`delta` -1) at `index`. */
export function shiftBlocks(blocks: SeqBlock[], index: number, delta: 1 | -1): SeqBlock[] {
  const shifted: SeqBlock[] = [];
  for (const block of blocks) {
    if (block.local >= index + (delta === 1 ? 0 : 1)) shifted.push({ ...block, local: block.local + delta });
    else if (index < block.local + block.length) shifted.push({ ...block, length: block.length + delta });
    else shifted.push(block);
  }
  return shifted.filter((block) => block.length > 0);
}

type EvictInput<TData> = {
  /** `evicted` flags before this commit; a repeated run of the updater picks the same blocks. */
  wasEvicted: readonly boolean[];
  loadedTotal: number;
  keep: RowRange;
  cap: number;
  protectedIds: ProtectedRows;
  idOf: (row: TData, index: number) => string;
};

/**
 * Unloads the blocks furthest from the keep range until the loaded rows fit `cap`; that is the front of the chain while the user scrolls down.
 * A block with a protected row stays whole. Writes the slots of `rows` in place.
 */
export function evictSequenceRows<TData>(core: Core<TData>, rows: (TData | undefined)[], { wasEvicted, loadedTotal, keep, cap, protectedIds, idOf }: EvictInput<TData>): (TData | undefined)[] {
  const { blocks } = core.seq;
  const centre = (keep.start + keep.end) / 2;
  const candidates = blocks.filter((block, index) => !wasEvicted[index] && !rangesIntersect({ start: block.local, end: block.local + block.length }, keep));
  candidates.sort((a, b) => distanceToCentre({ start: b.local, end: b.local + b.length }, centre) - distanceToCentre({ start: a.local, end: a.local + a.length }, centre) || a.local - b.local);
  let total = loadedTotal;
  let evicted = false;
  for (const block of candidates) {
    if (total <= cap) break;
    const range = { start: block.local, end: block.local + block.length };
    if (protectedIds !== null && protectedSlotsIn(rows, range, protectedIds, idOf).length > 0) continue;
    rows.fill(undefined, range.start, Math.min(range.end, rows.length));
    block.evicted = true;
    total -= block.length;
    evicted = true;
  }
  if (!evicted) return rows;
  core.loaded = sequenceLoaded(core.seq.length, blocks);
  core.unloaded = true;
  return rows;
}

import { groupIdOf, groupKeyText, type GroupPathSegment, type ServerGroupSlot } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { ServerGroupRow } from "./read-groups-answer";

/** The children of one group: its groups of the next level, or its rows. The top level has the id `""`. */
export type GroupList<TData> = {
  id: string;
  path: readonly GroupPathSegment[];
  kind: "groups" | "rows";
  /** `null` until the server answered the top level. */
  count: number | null;
  entries: (ServerGroupRow | TData | undefined)[];
  /** Loaded block index to the stamp of the latest report that kept it in view. */
  blocks: Map<number, number>;
  /** Key shifts seen since the lists were last reloaded; the second one fails the block. */
  conflicts: number;
};

/** Every list of an open or loaded group, by group id. */
export type GroupStore<TData> = { groupBy: readonly string[]; blockSize: number; lists: Map<string, GroupList<TData>>; leafCount: number | null };

/** The view rows of the open lists, in order, and where each one lives. */
export type GroupView<TData> = {
  /** One entry per view row; a group row and an unloaded row are `undefined`. */
  data: (TData | undefined)[];
  slots: ServerGroupSlot[];
  /** The list and the offset inside it of every view row. */
  owners: GroupList<TData>[];
  offsets: number[];
  leafCount: number;
  holes: number;
};

export const createGroupStore = <TData>(groupBy: readonly string[], blockSize: number): GroupStore<TData> => ({ groupBy, blockSize, lists: new Map(), leafCount: null });

export const blockOf = (offset: number, blockSize: number) => Math.floor(offset / blockSize);

export function listFor<TData>(store: GroupStore<TData>, path: readonly GroupPathSegment[], count: number | null): GroupList<TData> {
  const id = path.length === 0 ? "" : groupIdOf(path);
  let list = store.lists.get(id);
  if (!list) {
    list = { id, path, kind: path.length < store.groupBy.length ? "groups" : "rows", count, entries: [], blocks: new Map(), conflicts: 0 };
    store.lists.set(id, list);
  }
  return list;
}

function setCount<TData>(list: GroupList<TData>, count: number, blockSize: number) {
  list.count = count;
  if (list.entries.length > count) list.entries.length = count;
  for (const block of list.blocks.keys()) if (block * blockSize >= count) list.blocks.delete(block);
}

/** Writes a block of groups. Returns `"shifted"` when a key now sits at another offset than in a loaded block (the others drop), `"failed"` on a second shift. */
export function landGroups<TData>(store: GroupStore<TData>, list: GroupList<TData>, block: number, groups: readonly ServerGroupRow[], groupCount: number, stamp: number): "ok" | "shifted" | "failed" {
  const size = store.blockSize;
  const start = block * size;
  const elsewhere = new Map<string, number>();
  for (const other of list.blocks.keys()) {
    if (other === block) continue;
    for (let offset = other * size; offset < Math.min((other + 1) * size, list.entries.length); offset++) {
      const entry = list.entries[offset] as ServerGroupRow | undefined;
      if (entry) elsewhere.set(groupKeyText(entry.key), offset);
    }
  }
  const shifted = groups.some((group, index) => {
    const at = elsewhere.get(groupKeyText(group.key));
    return at !== undefined && at !== start + index;
  });
  if (shifted) {
    if (list.conflicts >= 1) return "failed";
    list.conflicts++;
    list.entries = [];
    list.blocks = new Map();
  }
  setCount(list, groupCount, size);
  groups.forEach((group, index) => {
    if (start + index < groupCount) list.entries[start + index] = group;
    const child = store.lists.get(groupIdOf([...list.path, { columnId: store.groupBy[list.path.length]!, key: group.key }]));
    if (child && child.count !== group.childCount) setCount(child, group.childCount, size);
  });
  list.blocks.set(block, stamp);
  return shifted ? "shifted" : "ok";
}

/** Writes a block of rows. `keep` names an existing row that a pending edit or save protects from the answer. */
export function landRows<TData>(store: GroupStore<TData>, list: GroupList<TData>, block: number, rows: readonly (TData | undefined)[], count: number | undefined, stamp: number, keep: (existing: TData, offset: number) => boolean) {
  const size = store.blockSize;
  if (count !== undefined) setCount(list, count, size);
  const start = block * size;
  rows.forEach((row, index) => {
    const offset = start + index;
    if (list.count !== null && offset >= list.count) return;
    const existing = list.entries[offset] as TData | undefined;
    if (existing !== undefined && keep(existing, offset)) return;
    list.entries[offset] = row;
  });
  list.blocks.set(block, stamp);
}

export function evictBlock<TData>(store: GroupStore<TData>, list: GroupList<TData>, block: number) {
  if (!list.blocks.delete(block)) return;
  const start = block * store.blockSize;
  const end = Math.min(start + store.blockSize, list.entries.length);
  for (let offset = start; offset < end; offset++) list.entries[offset] = undefined;
}

/** Lays the open lists out as view rows. A child list that is not loaded yet shows as unloaded rows, sized by the `childCount` of its group. `topWindow` cuts the top level to one page of groups. */
export function layoutView<TData>(store: GroupStore<TData>, isOpen: (groupId: string) => boolean, statusOf: (groupId: string) => "loading" | "failed" | undefined, topWindow?: { start: number; end: number }): GroupView<TData> {
  const view: GroupView<TData> = { data: [], slots: [], owners: [], offsets: [], leafCount: store.leafCount ?? 0, holes: 0 };
  const top = store.lists.get("");
  if (top?.count) walk(top);
  return view;

  function walk(list: GroupList<TData>) {
    const count = list.count ?? 0;
    const window = list.id === "" ? topWindow : undefined;
    for (let offset = window?.start ?? 0; offset < (window ? Math.min(count, window.end) : count); offset++) {
      const entry = list.entries[offset];
      view.owners.push(list);
      view.offsets.push(offset);
      if (list.kind === "rows" || entry === undefined) {
        view.data.push(entry as TData | undefined);
        if (entry === undefined) view.holes++;
        continue;
      }
      const group = entry as ServerGroupRow;
      const path = [...list.path, { columnId: store.groupBy[list.path.length]!, key: group.key }];
      const id = groupIdOf(path);
      const open = isOpen(id);
      const status = open ? statusOf(id) : undefined;
      view.slots.push({
        viewRow: view.data.length,
        path,
        count: group.totalRowCount,
        childCount: group.childCount,
        ...(group.label === undefined ? null : { label: group.label }),
        ...(group.aggregates ? { aggregates: group.aggregates } : null),
        ...(status ? { status } : null),
      });
      view.data.push(undefined);
      if (open) walk(listFor(store, path, group.childCount));
    }
  }
}

"use client";

import { useDataGridServerPager, type DataGridPaginationControls } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { DEFAULT_PAGE_SIZES } from "@/registry/default/components/data-grid-pagination/pagination-math";
import { createGroupStore, landGroups, listFor, type GroupStore } from "./group-lists";
import { readGroupsAnswer, type ServerGroupsAnswer } from "./read-groups-answer";

/** Pages mode of the group engine: the top level is one page of groups, and a block of any list holds `pageSize` entries. */
export type GroupPagesConfig = {
  page: number;
  pageSize: number;
  pageSizeOptions?: readonly number[];
  onPageChange: (page: number) => void;
  onPageSizeChange: (pageSize: number) => void;
};

export const pageWindowOf = (pages: GroupPagesConfig | undefined) => (pages ? { start: (pages.page - 1) * pages.pageSize, end: pages.page * pages.pageSize } : undefined);

export function isGroupsAnswer(answer: unknown): answer is ServerGroupsAnswer {
  return typeof answer === "object" && answer !== null && Array.isArray((answer as { groups?: unknown }).groups);
}

/** A store whose top level holds the `initialAnswer` as block `block`; `null` when the answer is not a usable groups answer. */
export function seedGroupStore<TData>(answer: unknown, groupBy: readonly string[], blockSize: number, block: number, aggregateIds: readonly string[]): GroupStore<TData> | null {
  if (!isGroupsAnswer(answer)) return null;
  try {
    const start = block * blockSize;
    const read = readGroupsAnswer(answer, { start, end: start + blockSize }, { topLevel: true, aggregateIds }, () => {});
    const store = createGroupStore<TData>(groupBy, blockSize);
    landGroups(store, listFor(store, [], null), block, read.groups, read.groupCount, 0);
    if (read.totalRowCount !== undefined) store.leafCount = read.totalRowCount;
    return store;
  } catch {
    return null;
  }
}

/** The pager of a grouped pages source: a page counts top-level groups. Inert (no count) without `pages`. */
export function useGroupPager(pages: GroupPagesConfig | undefined, groupCount: number | null): { pager: DataGridPaginationControls; plugins: ReturnType<typeof useDataGridServerPager>["gridProps"]["plugins"] } {
  const { pager, gridProps } = useDataGridServerPager({
    page: pages?.page ?? 1,
    pageSize: pages?.pageSize ?? 1,
    pageSizeOptions: pages?.pageSizeOptions ?? DEFAULT_PAGE_SIZES,
    totalRowCount: pages ? groupCount : null,
    unit: "groups",
    onPageChange: pages?.onPageChange ?? noop,
    onPageSizeChange: pages?.onPageSizeChange,
  });
  return { pager, plugins: gridProps.plugins };
}

function noop() {}

