type Flight = { list: GroupList<never>; block: number; controller: AbortController; ids: ReadonlySet<string> | null; mark: number };
type Failure = { listId: string; error: unknown };
function createEngine<TData>() {
  return {
    store: null as GroupStore<TData> | null,
    view: null as ViewState<TData> | null,
    flight: new Map<string, Flight>(),
    failed: new Map<string, Failure>(),
    stale: new Set<string>(),
    window: null as RowRange | null,
    reason: "load" as FetchReason,
    tick: 0,
    idIndex: null as Map<string, { list: GroupList<TData>; offset: number }> | null,
    landed: [] as { list: GroupList<TData>; start: number; end: number }[],
    cancelFrame: null as (() => void) | null,
    pumpTimer: null as ReturnType<typeof setTimeout> | null,
    warned: new Set<string>(),
  };
}
type Engine<TData> = ReturnType<typeof createEngine<TData>>;
type ViewState<TData> = GroupView<TData> & { loading: boolean; groupCount: number | null };

const emptyView = <TData,>(): ViewState<TData> => ({ data: [], slots: [], owners: [], offsets: [], leafCount: 0, holes: 0, loading: false, groupCount: null });

const positiveInteger = (value: number | undefined, fallback: number, min: number) => (typeof value === "number" && Number.isFinite(value) ? Math.max(min, Math.floor(value)) : fallback);

const blockSizeOf = (options: { blockSize?: number }, pages?: GroupPagesConfig) => pages?.pageSize ?? positiveInteger(options.blockSize, DEFAULT_BLOCK_SIZE, 1);

/** Whether the options opt in to grouping; read once per hook, so the choice holds for its life. */
export function groupsEnabled(options: { spec?: { groupBy?: unknown }; defaultSpec?: unknown; expanded?: unknown; defaultExpanded?: unknown; onExpandedChange?: unknown }): boolean {
  const seed = options.defaultSpec;
  const seeded = typeof seed === "object" && seed !== null && (seed as { groupBy?: unknown }).groupBy !== undefined;
  return options.spec?.groupBy !== undefined || seeded || options.expanded !== undefined || options.defaultExpanded !== undefined || options.onExpandedChange !== undefined;
}

/**
 * The group engine of scroll mode: one list per open group, loaded by offset in blocks. The core lays the group rows out from the
 * `groupLayout` this hook builds, and `data` holds one entry per view row. Group requests carry offsets, never a cursor.
 */
export function useGroupBlocks<TData, TCursor = never>(
  options: WithRowId<UseDataGridServerRowsScrollOptions<TData, TCursor> & UseDataGridServerRowsGroupOptions, TData>,
  specState: ServerSpecState,
  active: boolean,
  pages?: GroupPagesConfig,
) {
  const { spec, onSortChange, onFilterChange, onFilterJoinChange, onSearchTextChange, onGroupByChange } = specState;
  const groupBy = spec.groupBy ?? NO_GROUPS;
  const requestKey = serverSpecKey({ ...spec, aggregates: undefined });
  const engineKey = pages ? `${requestKey}|${pages.pageSize}` : requestKey;
  const aggregateKey = JSON.stringify(spec.aggregates ?? []);
  const [rawExpanded, setExpanded] = useControlled(options.expanded, () => options.defaultExpanded ?? COLLAPSED, options.onExpandedChange);
  const expanded = useMemo(() => (normalizeExpanded(rawExpanded).mode === "collapsed" ? normalizeExpanded(rawExpanded) : COLLAPSED), [rawExpanded]);
  const aggregateIds = () => (spec.aggregates ?? []).map((aggregate) => aggregate.columnId);
  const [seed] = useState(() => (active && isGroupsAnswer(options.initialAnswer) ? { answer: options.initialAnswer, key: engineKey } : null));
  const [view, setView] = useState<ViewState<TData>>(() => {
    const store = seed && seedGroupStore<TData>(seed.answer, groupBy, blockSizeOf(options, pages), (pages?.page ?? 1) - 1, aggregateIds());
    return store ? { ...layoutView(store, expandedTest(expanded), () => undefined, pageWindowOf(pages)), loading: false, groupCount: store.lists.get("")?.count ?? null } : emptyView();
  });
  const [error, setError] = useState<unknown>(null);
  const { plugins: guardPlugins, protectedRows, savingRows, saveMark, savedSince, pruneSaves, overlayPushed, streamUpdateRow, setSettleListener, setReshapeListener, evictionProtected } = useRefreshGuard({ trackUnacknowledged: true });
  const { pager, plugins: pagerPlugins } = useGroupPager(pages, view.groupCount);
  const seedRef = useRef(seed);

  const live = useRef({ options, spec, expanded, groupBy, active, pages, engineKey });
  useLayoutEffect(() => {
    live.current = { options, spec, expanded, groupBy, active, pages, engineKey };
  });
  const engineRef = useRef<Engine<TData> | null>(null);
  const getEngine = useCallback((): Engine<TData> => {
    if (engineRef.current === null) engineRef.current = createEngine<TData>();
    return engineRef.current;
  }, []);

  const warn = useCallback(
    (kind: string, message: string) => {
      if (!isDev() || getEngine().warned.has(kind)) return;
      getEngine().warned.add(kind);
      console.warn(`[data-grid-server] ${message}`);
    },
    [getEngine],
  );
  const blockSize = () => blockSizeOf(live.current.options, live.current.pages);
  const overscan = () => positiveInteger(live.current.options.overscan, DEFAULT_OVERSCAN, 0);
  const idOf = (row: TData, index: number) => live.current.options.getRowId(row, index);

  const syncError = () => setError(getEngine().failed.size > 0 ? [...getEngine().failed.values()].at(-1)!.error : null);

  const publish = () => {
    const store = getEngine().store;
    if (!store) {
      getEngine().view = null;
      setView((prev) => (prev.data.length === 0 && prev.slots.length === 0 && !prev.loading && prev.groupCount === null ? prev : emptyView()));
      return;
    }
    const states = new Map<string, "loading" | "failed">();
    for (const { listId } of getEngine().failed.values()) states.set(listId, "failed");
    for (const { list } of getEngine().flight.values()) if (!states.has(list.id)) states.set(list.id, "loading");
    const next = { ...layoutView(store, expandedTest(live.current.expanded), (id) => states.get(id), pageWindowOf(live.current.pages)), loading: getEngine().flight.size > 0, groupCount: store.lists.get("")?.count ?? null } satisfies ViewState<TData>;
    getEngine().view = next;
    setView(next);
    const { onLoaded } = live.current.options;
    for (const { list, start, end } of getEngine().landed.splice(0)) {
      const first = firstViewRow(next, list, start);
      if (first !== -1 && onLoaded) isolate("onLoaded", () => onLoaded({ start: first, end: first + (end - start) }));
    }
  };
  const schedulePublish = () => {
    if (getEngine().cancelFrame !== null) return;
    getEngine().cancelFrame = scheduleFrame(() => {
      getEngine().cancelFrame = null;
      publish();
      pump();
    });
  };

  const abortAll = () => {
    for (const { controller } of getEngine().flight.values()) controller.abort();
    getEngine().flight.clear();
  };

  const fail = (key: string, list: GroupList<TData>, error: unknown) => {
    getEngine().failed.set(key, { listId: list.id, error: error ?? new Error("fetchRows rejected") });
    syncError();
    const { onError } = live.current.options;
    if (onError) isolate("onError", () => onError(error));
    schedulePublish();
  };

  const evictOverCap = (store: GroupStore<TData>) => {
    const cap = live.current.options.maxLoadedRows;
    const limit = typeof cap === "number" && !Number.isNaN(cap) ? Math.max(cap, store.blockSize) : DEFAULT_MAX_LOADED_ROWS;
    const loaded: { list: GroupList<TData>; block: number; stamp: number }[] = [];
    for (const list of store.lists.values()) if (list.kind === "rows") for (const entry of list.blocks) loaded.push({ list, block: entry[0], stamp: entry[1] });
    let rows = loaded.length * store.blockSize;
    if (rows <= limit) return;
    const protectedIds = evictionProtected();
    loaded.sort((a, b) => a.stamp - b.stamp);
    for (const { list, block, stamp } of loaded) {
      if (rows <= limit || stamp >= getEngine().tick - 1) break;
      const start = block * store.blockSize;
      const held = protectedIds && list.entries.slice(start, start + store.blockSize).some((row) => row !== undefined && protectedIds.has(idOf(row as TData, start)));
      if (held) continue;
      evictBlock(store, list, block);
      rows -= store.blockSize;
      getEngine().idIndex = null;
    }
  };

  /** Writes a validated answer into its list; returns the failure instead of throwing, so `land` keeps one try block. */
  const writeAnswer = (store: GroupStore<TData>, list: GroupList<TData>, flight: Flight, answer: unknown, range: RowRange): Error | null => {
    const stamp = ++getEngine().tick;
    if (list.kind === "groups") {
      const aggregateIds = (live.current.spec.aggregates ?? []).map((aggregate) => aggregate.columnId);
      const read = readGroupsAnswer(answer, range, { topLevel: list.id === "", aggregateIds }, warn);
      if (landGroups(store, list, flight.block, read.groups, read.groupCount, stamp) === "failed") return new TypeError("fetchRows answered groups that shifted twice since the last reload; make the group order total");
      if (list.id === "" && read.totalRowCount !== undefined) store.leafCount = read.totalRowCount;
      return null;
    }
    const read = readAnswer<TData, TCursor>(answer, range, warn, idOf);
    assertRowIdsNotReserved(read.rows.flatMap((row, index) => (row === undefined ? [] : [idOf(row, range.start + index)])));
    const guarded = unionIds(unionIds(flight.ids, savedSince(flight.mark)), protectedRows());
    const count = typeof read.totalRowCount === "number" ? read.totalRowCount : undefined;
    landRows(store, list, flight.block, overlayPushed(read.rows as TData[], flight.mark, range.start, idOf), count, stamp, (existing, offset) => guarded?.has(idOf(existing, offset)) === true);
    return null;
  };

  const land = (key: string, flight: Flight, answer: unknown, range: RowRange) => {
    const store = getEngine().store!;
    const list = flight.list as unknown as GroupList<TData>;
    getEngine().flight.delete(key);
    getEngine().stale.delete(key);
    let failure: unknown = null;
    try {
      failure = writeAnswer(store, list, flight, answer, range);
    } catch (error) {
      failure = error;
    }
    if (failure !== null) {
      fail(key, list, failure);
      return;
    }
    getEngine().failed.delete(key);
    syncError();
    getEngine().idIndex = null;
    getEngine().landed.push({ list, start: range.start, end: range.start + (range.end - range.start) });
    evictOverCap(store);
    pruneSaves([...getEngine().flight.values()].reduce<number | null>((oldest, { mark }) => (oldest === null || mark < oldest ? mark : oldest), null));
    schedulePublish();
  };

  const fetchBlock = (list: GroupList<TData>, block: number) => {
    const key = `${list.id}|${block}`;
    const size = blockSize();
    const start = block * size;
    const range = { start, end: list.count === null ? start + size : Math.min(start + size, list.count) };
    const controller = new AbortController();
    const flight: Flight = { list: list as unknown as GroupList<never>, block, controller, ids: savingRows(), mark: saveMark() };
    getEngine().flight.set(key, flight);
    const base: ServerRowsRequest<TCursor> = { spec: live.current.spec, ...range, cursor: undefined, reason: getEngine().reason, signal: controller.signal, groupPath: list.path, childKind: list.kind };
    const request = live.current.pages ? { ...base, page: block + 1, pageSize: size } : base;
    const settled = () => getEngine().flight.get(key)?.controller === controller && !controller.signal.aborted;
    new Promise<unknown>((resolve) => resolve(live.current.options.fetchRows(request))).then(
      (answer) => settled() && land(key, flight, answer, range),
      (error: unknown) => {
        if (!settled()) return;
        getEngine().flight.delete(key);
        fail(key, list, error);
      },
    );
  };

  /** Blocks under the rendered rows plus overscan, nearest to the middle first. */
  const wantedBlocks = (store: GroupStore<TData>) => {
    const found = new Map<string, { list: GroupList<TData>; block: number; distance: number }>();
    const top = listFor(store, [], null);
    found.set(`|${(live.current.pages?.page ?? 1) - 1}`, { list: top, block: (live.current.pages?.page ?? 1) - 1, distance: -1 });
    const { window: range, view: laid } = getEngine();
    if (!range || !laid) return found;
    const middle = (range.start + range.end) / 2;
    const from = Math.max(0, range.start - overscan());
    const to = Math.min(laid.data.length, range.end + overscan());
    for (let row = from; row < to; row++) {
      const list = laid.owners[row]!;
      const block = blockOf(laid.offsets[row]!, store.blockSize);
      const key = `${list.id}|${block}`;
      if (!found.has(key)) found.set(key, { list, block, distance: Math.abs(row - middle) });
    }
    return found;
  };

  const newStore = () => {
    const { groupBy: by, pages: paging, engineKey: key } = live.current;
    const pending = seedRef.current;
    const seeded = pending?.key === key ? seedGroupStore<TData>(pending.answer, by, blockSize(), (paging?.page ?? 1) - 1, (live.current.spec.aggregates ?? []).map((aggregate) => aggregate.columnId)) : null;
    return seeded ?? createGroupStore<TData>(by, blockSize());
  };

  const seedStore = () => {
    if (seedRef.current?.key === live.current.engineKey) getEngine().store = newStore();
  };

  const pump = () => {
    if (!live.current.active) return;
    const store = getEngine().store ?? newStore();
    getEngine().store = store;
    const wanted = wantedBlocks(store);
    for (const [key, flight] of getEngine().flight) {
      if (wanted.has(key)) continue;
      flight.controller.abort();
      getEngine().flight.delete(key);
    }
    const limit = Math.min(positiveInteger(live.current.options.maxConcurrentFetches, DEFAULT_CONCURRENT, 1), MAX_CONCURRENT);
    const due = [...wanted]
      .filter(([key, { list, block }]) => !getEngine().flight.has(key) && !getEngine().failed.has(key) && (!list.blocks.has(block) || getEngine().stale.has(key)))
      .sort((a, b) => a[1].distance - b[1].distance);
    for (const entry of wanted.values()) if (entry.list.blocks.has(entry.block)) entry.list.blocks.set(entry.block, ++getEngine().tick);
    let started = false;
    for (const [, entry] of due) {
      if (getEngine().flight.size >= limit) break;
      fetchBlock(entry.list, entry.block);
      started = true;
    }
    if (started) schedulePublish();
  };

  const pumpSoon = (immediate: boolean) => {
    const delay = positiveInteger(live.current.options.loadDelayMs, DEFAULT_LOAD_DELAY_MS, 0);
    const engine = getEngine();
    if (engine.pumpTimer !== null) clearTimeout(engine.pumpTimer);
    engine.pumpTimer = null;
    if (immediate || delay === 0) pump();
    else engine.pumpTimer = setTimeout(() => ((engine.pumpTimer = null), pump()), delay);
  };

  const reset = () => {
    const engine = getEngine();
    abortAll();
    if (engine.pumpTimer !== null) clearTimeout(engine.pumpTimer);
    engine.pumpTimer = null;
    engine.cancelFrame?.();
    engine.cancelFrame = null;
    engine.store = null;
    engine.view = null;
    engine.idIndex = null;
    engine.failed.clear();
    engine.stale.clear();
    engine.landed = [];
    engine.reason = "load";
    pruneSaves(null);
    setError(null);
  };

  const staleGroupBlocks = () => {
    const engine = getEngine();
    if (!engine.store) return;
    for (const list of engine.store.lists.values()) if (list.kind === "groups") for (const block of list.blocks.keys()) engine.stale.add(`${list.id}|${block}`);
    pump();
  };

  const loading = view.loading;
  const apiRef = useRef({ seedStore: noop, pump: noop, pumpSoon: noopFlag, publish: noop, reset: noop, refreshFor: noopReason, staleGroupBlocks: noop, retry: noop, applyUpdates: noopChange, evictRange: noopRange });
  const { request: requestReshape, cancel: cancelReshape } = useReshape({ delay: active ? options.reshapeDelayMs : false, ordered: spec.sorts.length + spec.filters.length > 0, run: () => apiRef.current.refreshFor("refresh"), busy: loading, resetKey: requestKey, warn });
  const restartClock = useRevalidation({ interval: active ? options.revalidateIntervalMs : undefined, onTick: () => apiRef.current.refreshFor("refresh"), busy: loading, resetKey: requestKey });

  const refreshFor = (reason: FetchReason) => {
    const engine = getEngine();
    cancelReshape();
    restartClock();
    engine.reason = reason;
    abortAll();
    engine.failed.clear();
    engine.stale.clear();
    syncError();
    const store = engine.store;
    if (store) {
      const keep = wantedBlocks(store);
      for (const list of store.lists.values()) {
        list.conflicts = 0;
        for (const block of Array.from(list.blocks.keys())) {
          const key = `${list.id}|${block}`;
          if (list.kind === "groups" || keep.has(key)) engine.stale.add(key);
          else evictBlock(store, list, block);
        }
      }
      engine.idIndex = null;
    }
    pump();
    schedulePublish();
  };

  const retryFailed = () => {
    const engine = getEngine();
    engine.failed.clear();
    syncError();
    engine.reason = "retry";
    pump();
    schedulePublish();
  };

  const evictRange = (range: RowRange) => {
    const engine = getEngine();
    const store = engine.store;
    const laid = engine.view;
    if (!store || !laid) return;
    for (let row = Math.max(0, range.start); row < Math.min(range.end, laid.data.length); row++) {
      const list = laid.owners[row]!;
      if (list.kind === "rows") evictBlock(store, list, blockOf(laid.offsets[row]!, store.blockSize));
    }
    engine.idIndex = null;
    publish();
  };

  const applyUpdates = (change: DataChange<TData>) => {
    const engine = getEngine();
    const store = engine.store;
    if (!store) return;
    const index = engine.idIndex ?? indexRows(store, idOf);
    engine.idIndex = index;
    const rowOf = streamUpdateRow(change);
    let written = false;
    for (const op of change.ops) {
      if (op.type !== "update") {
        warn("rows-ignored", "an insert, delete, or move reached a grouped source and was ignored; the server places rows while the grid is grouped");
        continue;
      }
      const at = index.get(op.rowId);
      if (!at) continue;
      at.list.entries[at.offset] = rowOf ? rowOf(op, at.list.entries[at.offset] as TData) : op.row;
      written = true;
    }
    if (written) publish();
    if (change.source === "stream" && change.ops.some((op) => op.type !== "update")) requestReshape("soon");
  };

  useLayoutEffect(() => {
    apiRef.current = { seedStore, pump, pumpSoon, publish, reset, refreshFor, staleGroupBlocks, retry: retryFailed, applyUpdates: applyUpdates as (change: DataChange<never>) => void, evictRange };
  });

  const onRenderedRowsChange = useCallback(
    (range: RowRange) => {
      getEngine().window = range;
      apiRef.current.pumpSoon(false);
      isolate("onRenderedRowsChange", () => live.current.options.onRenderedRowsChange?.(range));
    },
    [getEngine],
  );

  // A new request key drops every list and fetches the top level again; `expanded` stays, because group ids come from the keys.
  useLayoutEffect(() => {
    if (seedRef.current && seedRef.current.key !== engineKey) seedRef.current = null;
    apiRef.current.reset();
    if (active) apiRef.current.seedStore();
    apiRef.current.publish();
    if (!active) return;
    const timer = setTimeout(() => apiRef.current.pump(), 0);
    return () => {
      clearTimeout(timer);
      apiRef.current.reset();
    };
  }, [engineKey, active]);

  // Aggregates change the group rows only: reload their blocks in place and keep the lists and the scroll position.
  const firstAggregates = useRef(aggregateKey);
  useEffect(() => {
    if (firstAggregates.current === aggregateKey) return;
    firstAggregates.current = aggregateKey;
    apiRef.current.staleGroupBlocks();
  }, [aggregateKey]);

  // A toggle lays the view out again and asks for the rows the open group shows.
  useLayoutEffect(() => {
    if (!getEngine().store) return;
    apiRef.current.publish();
    apiRef.current.pumpSoon(true);
  }, [expanded, pages?.page, getEngine]);

  const refresh = useCallback(() => apiRef.current.refreshFor("refresh"), []);
  const retry = useCallback(() => apiRef.current.retry(), []);
  const reshape = useCallback(() => requestReshape("soon"), [requestReshape]);
  useEffect(() => {
    setReshapeListener(requestReshape);
    return () => setReshapeListener(null);
  }, [setReshapeListener, requestReshape]);
  useEffect(() => {
    setSettleListener(() => {
      if (live.current.options.refreshAfterSave !== false) apiRef.current.refreshFor("save");
    });
    return () => setSettleListener(null);
  }, [setSettleListener]);

  const handledChanges = useRef(new WeakSet<object>());
  const onDataChange = useCallback(
    (next: readonly TData[], change: DataChange<TData>) => {
      if (handledChanges.current.has(change)) return;
      handledChanges.current.add(change);
      apiRef.current.applyUpdates(change as DataChange<never>);
      const onChange = live.current.options.onDataChange;
      if (onChange) isolate("onDataChange", () => onChange(next, change));
    },
    [],
  );

  const refreshAfterSave = useCallback(() => apiRef.current.refreshFor("save"), []);
  const { onSave, wrapSave } = useSaveRefresh({ onSave: options.onSave, refreshAfterSave: options.refreshAfterSave as SaveRefreshPolicy | undefined }, refreshAfterSave);
  const paged = pages !== undefined;
  const ownPlugins = useMemo(() => (paged ? [...guardPlugins, ...pagerPlugins] : guardPlugins), [paged, guardPlugins, pagerPlugins]);
  const plugins = useMountedPlugins(ownPlugins, options.plugins);
  const getRowId = useCallback((row: TData, index: number) => (row === undefined ? holeRowId(index) : live.current.options.getRowId(row, index)), []);
  const groupLayout = useMemo<ServerGroupLayout>(() => ({ rows: view.slots, leafCount: view.leafCount }), [view]);

  const providerProps = useMemo<UseDataGridServerRowsScrollProviderProps<TData>>(
    () => ({
      data: view.data as TData[],
      getRowId,
      onDataChange,
      ...(onSave ? { onSave } : {}),
      onRenderedRowsChange,
      sortMode: "server",
      filterMode: "server",
      sortState: spec.sorts as UseDataGridServerRowsScrollProviderProps<TData>["sortState"],
      onSortChange,
      filterState: spec.filters as UseDataGridServerRowsScrollProviderProps<TData>["filterState"],
      onFilterChange,
      filterJoin: spec.filterJoin ?? "and",
      onFilterJoinChange,
      searchText: spec.searchText,
      onSearchTextChange,
      totalRowCount: view.data.length,
      checkedRowsLifetime: "across-filters",
      headerClickBehavior: "sort",
      plugins,
      groupBy,
      onGroupByChange,
      expanded,
      onExpandedChange: setExpanded,
      groupMode: "server",
      groupLayout,
    }),
    [view, getRowId, onDataChange, onSave, onRenderedRowsChange, spec, onSortChange, onFilterChange, onFilterJoinChange, onSearchTextChange, plugins, groupBy, onGroupByChange, expanded, setExpanded, groupLayout],
  );
  useRegisteredWiring(providerProps, wrapSave);
  const rootProps = useMemo<UseDataGridServerRowsRootProps>(() => ({ loading, error, onRetry: retry }), [loading, error, retry]);
  const gridProps = useMemo(() => ({ ...providerProps, ...rootProps }), [providerProps, rootProps]);

  const getLoadedRanges = useCallback((): readonly RowRange[] => {
    const ranges: RowRange[] = [];
    const data = getEngine().view?.data ?? [];
    const slots = new Set(getEngine().view?.slots.map((slot) => slot.viewRow));
    data.forEach((row, index) => {
      if (row === undefined && !slots.has(index)) return;
      const last = ranges.at(-1);
      if (last && last.end === index) last.end = index + 1;
      else ranges.push({ start: index, end: index + 1 });
    });
    return ranges;
  }, [getEngine]);
  const evict = useCallback((range: RowRange) => apiRef.current.evictRange(range), []);

  const status = error !== null ? "error" : loading ? "loading" : "ready";
  const result: UseDataGridServerRowsScrollResult<TData> = { gridProps, providerProps, rootProps, spec, totalRowCount: view.leafCount, status, loading, error, retry, refresh, reshape, canRevalidate: () => true, unloadedCount: view.holes, getLoadedRanges, evict };
  const groupProps = useMemo(() => ({ groupBy, onGroupByChange, expanded, onExpandedChange: setExpanded }), [groupBy, onGroupByChange, expanded, setExpanded]);
  return { result, groupProps, pager, pagerPlugins, groupCount: view.groupCount };
}

function noop() {}
const noopFlag = (_immediate: boolean) => {};
const noopReason = (_reason: FetchReason) => {};
const noopChange = (_change: DataChange<never>) => {};
const noopRange = (_range: RowRange) => {};

function firstViewRow<TData>(view: GroupView<TData>, list: GroupList<TData>, offset: number): number {
  for (let row = 0; row < view.owners.length; row++) if (view.owners[row] === list && view.offsets[row] === offset) return row;
  return -1;
}

function indexRows<TData>(store: GroupStore<TData>, idOf: (row: TData, index: number) => string) {
  const index = new Map<string, { list: GroupList<TData>; offset: number }>();
  for (const list of store.lists.values()) {
    if (list.kind !== "rows") continue;
    list.entries.forEach((row, offset) => {
      if (row !== undefined) index.set(idOf(row as TData, offset), { list, offset });
    });
  }
  return index;
}

"use client";

import { useMemo, useState } from "react";
import type { WithRowId } from "./read-answer";
import { useScrollBlocks, type UseDataGridServerRowsScrollOptions } from "./scroll-blocks";
import type { UseDataGridServerRowsScrollResult } from "./scroll-types";
import { useServerSpec } from "./server-state";
import { groupsEnabled, useGroupBlocks, type UseDataGridServerRowsGroupOptions } from "./use-group-blocks";

function noop() {}

type Options<TData, TCursor> = WithRowId<UseDataGridServerRowsScrollOptions<TData, TCursor> & UseDataGridServerRowsGroupOptions, TData>;

/**
 * Scroll mode: the flat block engine, plus the group engine when the options opt in to grouping. Both read one spec. While the
 * spec groups, the flat engine waits (`ready: false`) and the group engine fetches; an empty `groupBy` hands the rows back.
 */
export function useScrollRows<TData, TCursor = never>(options: Options<TData, TCursor>): UseDataGridServerRowsScrollResult<TData> {
  const [grouping] = useState(() => groupsEnabled(options));
  const specState = useServerSpec(options, noop, grouping);
  const grouped = grouping && (specState.spec.groupBy?.length ?? 0) > 0;
  const flatSpec = useMemo(() => (grouped ? { ...specState, ready: false } : specState), [grouped, specState]);
  const flat = useScrollBlocks(options, flatSpec);
  const groups = useGroupBlocks(options, specState, grouped);
  const extra = grouping ? groups.groupProps : undefined;
  const gridProps = useMemo(() => (extra ? { ...flat.gridProps, ...extra } : flat.gridProps), [flat.gridProps, extra]);
  const providerProps = useMemo(() => (extra ? { ...flat.providerProps, ...extra } : flat.providerProps), [flat.providerProps, extra]);
  const ungrouped = useMemo(() => ({ ...flat, gridProps, providerProps }), [flat, gridProps, providerProps]);
  return grouped ? groups.result : ungrouped;
}

"use client";

import { useCallback, useEffect, useState } from "react";
import type { DataChange, DataGridPlugin, DataGridReadState, DataGridStoreWrapper } from "@/registry/default/components/data-grid/data-grid";
import { rowIdAtViewRow, setCellValue, setServerReshapeHandler, useDataGridStoreApi } from "@/registry/default/components/data-grid/data-grid-sdk";

/**
 * The rule: a block that lands (refresh, retry or window load) replaces every row it carries, except a row that has a pending
 * cell edit or a save that was in flight at any moment since the request was sent: that row keeps its local value. A row with
 * a pending delete is gone: the answer's copy is dropped and its slot stays empty. A protected row that the answer lacks, such as a
 * pending insert, returns to its own slot when no answer row sits there; otherwise it is hidden, and a counted source refreshes
 * when no pending insert or delete is left. A pages refresh appends such a row at the page end (the page can exceed `pageSize`
 * by pending inserts); a sequential refresh that ends before a pending insert may drop it until its save settles.
 * Everything else is replaced, except the cells that a push wrote after the request was sent: those keep the pushed value. A block shows each id once (the first row of a repeated id in an answer wins) and leaves no hole in its
 * loaded range; rows that moved on the server can mix with older rows until the next refresh settles.
 */

/** The rows an answer must not overwrite: a save is pending, or an edit session is open. */
export type ProtectedRows = ReadonlySet<string> | null;

type Holder = {
  store: DataGridStoreWrapper | null;
  generation: number;
  /** Saves are tracked only while a request is open. */
  recording: boolean;
  /** Row id -> generation of its latest save start; holds one entry per saved row, dropped when no request is open. */
  savedAt: Map<string, number>;
  /** Rows of a local insert or delete whose save is pending. */
  structural: Set<string>;
  /** Called when the last pending insert or delete save settled. */
  onStructuralSettled: (() => void) | null;
  /** Called when a row's save starts. */
  onSaveStarted: (() => void) | null;
  /** Called when the last saving row leaves `"saving"`. */
  onSavesSettled: (() => void) | null;
  /** Called when the grid asks for a reshape: `reconcileView()`, an immediate push, or a deferred push that marked a row. */
  onReshape: ((trigger: "urgent" | "stale") => void) | null;
  /** Cells that a push wrote while a request was open: row id -> column id -> value and the generation of the push. Dropped when no request is open. */
  pushed: Map<string, Map<string, { value: unknown; at: number }>>;
  trackUnacknowledged: boolean;
  /** Rows with a local edit or insert that no save and no landed block has acknowledged; eviction keeps them. */
  unacknowledged: Set<string>;
};

function setListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onStructuralSettled = listener;
}

function setSaveListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onSaveStarted = listener;
}

function setSettledListenerOn(holder: Holder, listener: (() => void) | null) {
  holder.onSavesSettled = listener;
}

function setReshapeOn(holder: Holder, listener: ((trigger: "urgent" | "stale") => void) | null) {
  holder.onReshape = listener;
}

function hasSaving(status: ReadonlyMap<string, string>): boolean {
  for (const value of status.values()) if (value === "saving") return true;
  return false;
}

function trackStructural(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string }[] }) {
  if (change.source === "stream" || change.source === "rollback") return;
  const status = holder.store?.getState().saveStatus;
  for (const op of change.ops) if ((op.type === "insert" || op.type === "delete") && status?.get(op.rowId) === "saving") holder.structural.add(op.rowId);
}

function trackUnacknowledgedRows(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string }[] }) {
  if (!holder.trackUnacknowledged || change.source === "stream" || change.source === "rollback") return;
  for (const op of change.ops) {
    if (op.type === "update" || op.type === "insert") holder.unacknowledged.add(op.rowId);
    else if (op.type === "delete") holder.unacknowledged.delete(op.rowId);
  }
}

function trackPushedCells(holder: Holder, change: { source: string; ops: readonly { type: string; rowId: string; cells?: readonly { columnId: string; value: unknown }[] }[] }) {
  if (!holder.recording || change.source !== "stream") return;
  for (const op of change.ops) {
    if (op.type !== "update" || !op.cells) continue;
    const at = ++holder.generation;
    let cells = holder.pushed.get(op.rowId);
    if (!cells) holder.pushed.set(op.rowId, (cells = new Map<string, { value: unknown; at: number }>()));
    for (const cell of op.cells) cells.set(cell.columnId, { value: cell.value, at });
  }
}

function pushedSinceOn(holder: Holder, generation: number): ReadonlyMap<string, ReadonlyMap<string, unknown>> | null {
  let rows: Map<string, Map<string, unknown>> | null = null;
  for (const [rowId, cells] of holder.pushed) {
    let fresh: Map<string, unknown> | null = null;
    for (const [columnId, cell] of cells) if (cell.at > generation) (fresh ??= new Map()).set(columnId, cell.value);
    if (fresh) (rows ??= new Map()).set(rowId, fresh);
  }
  return rows;
}

function trackSaves(holder: Holder, state: DataGridReadState, prev: DataGridReadState) {
  if (state.saveStatus === prev.saveStatus) return;
  if (holder.unacknowledged.size > 0) {
    for (const [id, status] of prev.saveStatus) if (status === "saving" && state.saveStatus.get(id) !== "saving") holder.unacknowledged.delete(id);
  }
  if (holder.structural.size > 0) {
    for (const [id, status] of prev.saveStatus) {
      if (status === "saving" && state.saveStatus.get(id) !== "saving" && holder.structural.delete(id) && holder.structural.size === 0) holder.onStructuralSettled?.();
    }
  }
  let started = false;
  for (const [id, status] of state.saveStatus) {
    if (status !== "saving" || prev.saveStatus.get(id) === "saving") continue;
    started = true;
    if (holder.recording) holder.savedAt.set(id, ++holder.generation);
  }
  if (started) {
    holder.onSaveStarted?.();
  }
  if (holder.onSavesSettled && hasSaving(prev.saveStatus) && !hasSaving(state.saveStatus)) holder.onSavesSettled();
}

function savedSinceOn(holder: Holder, generation: number): ProtectedRows {
  let ids: Set<string> | null = null;
  for (const [id, at] of holder.savedAt) if (at > generation) (ids ??= new Set()).add(id);
  return ids;
}

function markSavesOn(holder: Holder): number {
  holder.recording = true;
  return holder.generation;
}

function pruneSavesOn(holder: Holder, oldestGeneration: number | null) {
  holder.recording = oldestGeneration !== null;
  if (oldestGeneration === null) {
    holder.savedAt.clear();
    holder.pushed.clear();
    return;
  }
  for (const [id, at] of holder.savedAt) if (at <= oldestGeneration) holder.savedAt.delete(id);
  for (const [id, cells] of holder.pushed) {
    for (const [columnId, cell] of cells) if (cell.at <= oldestGeneration) cells.delete(columnId);
    if (cells.size === 0) holder.pushed.delete(id);
  }
}

function createGuardPlugin(holder: Holder): DataGridPlugin<unknown> {
  function RefreshGuardMount() {
    const store = useDataGridStoreApi();
    useEffect(() => {
      holder.store = store;
      const unsubscribe = store.subscribe((state, prev) => trackSaves(holder, state, prev));
      setServerReshapeHandler(store, (trigger) => holder.onReshape?.(trigger));
      return () => {
        setServerReshapeHandler(store, null);
        unsubscribe();
        holder.store = null;
      };
    }, [store]);
    return null;
  }
  return {
    name: "server-rows-refresh-guard",
    Mount: RefreshGuardMount,
    onDataChange: (_next, change) => {
      trackStructural(holder, change);
      trackUnacknowledgedRows(holder, change);
      trackPushedCells(holder, change);
    },
  };
}

export type RefreshGuardOptions = {
  /** Remember rows with a local change that no save acknowledged, for `evictionProtected`. Scroll mode only. */
  trackUnacknowledged?: boolean;
};

/** A plugin that gives the hook, which sits outside the provider, read access to the grid's save status and edit session. */
export function useRefreshGuard({ trackUnacknowledged = false }: RefreshGuardOptions = {}) {
  const [holder] = useState<Holder>(() => ({ store: null, generation: 0, recording: false, savedAt: new Map(), structural: new Set(), onStructuralSettled: null, onSaveStarted: null, onSavesSettled: null, onReshape: null, pushed: new Map(), trackUnacknowledged, unacknowledged: new Set() }));
  const [plugins] = useState(() => [createGuardPlugin(holder)]);
  const savingRows = useCallback((): ProtectedRows => {
    const state = holder.store?.getState();
    if (!state) return null;
    const ids = new Set<string>();
    for (const [rowId, status] of state.saveStatus) if (status === "saving") ids.add(rowId);
    return ids.size > 0 ? ids : null;
  }, [holder]);
  const protectedRows = useCallback((): ProtectedRows => {
    const editing = holder.store?.getState().editing;
    return editing ? unionIds(savingRows(), new Set([editing.rowId])) : savingRows();
  }, [holder, savingRows]);
  const saveMark = useCallback(() => markSavesOn(holder), [holder]);
  const savedSince = useCallback((mark: number) => savedSinceOn(holder, mark), [holder]);
  const setSettleListener = useCallback((listener: (() => void) | null) => setListenerOn(holder, listener), [holder]);
  const setSaveStartListener = useCallback((listener: (() => void) | null) => setSaveListenerOn(holder, listener), [holder]);
  const setSavesSettledListener = useCallback((listener: (() => void) | null) => setSettledListenerOn(holder, listener), [holder]);
  const setReshapeListener = useCallback((listener: ((trigger: "urgent" | "stale") => void) | null) => setReshapeOn(holder, listener), [holder]);
  const forgetStructural = useCallback(() => {
    holder.structural.clear();
    holder.unacknowledged.clear();
  }, [holder]);
  const evictionProtected = useCallback((): ProtectedRows => {
    const ids = holder.unacknowledged.size > 0 ? unionIds(protectedRows(), holder.unacknowledged) : protectedRows();
    const state = holder.store?.getState();
    const active = state?.activeCell ? rowIdAtViewRow(state, state.activeCell.row) : undefined;
    return active === undefined ? ids : unionIds(ids, new Set([active]));
  }, [holder, protectedRows]);
  const acknowledge = useCallback((rowId: string) => holder.unacknowledged.delete(rowId), [holder]);
  const unacknowledgedRows = useCallback((): ReadonlySet<string> | null => (holder.unacknowledged.size > 0 ? holder.unacknowledged : null), [holder]);
  const pruneSaves = useCallback((oldestMark: number | null) => pruneSavesOn(holder, oldestMark), [holder]);
  const streamUpdateRow = useCallback(
    <TData,>(change: DataChange<TData>) => {
      const columns = holder.store?.getState().columns;
      return columns ? rowOfStreamUpdate(change, columns) : undefined;
    },
    [holder],
  );
  const overlayPushed = useCallback(
    <TData,>(rows: readonly TData[], mark: number, start: number, idOf: (row: TData, index: number) => string): TData[] => {
      const pushed = pushedSinceOn(holder, mark);
      const columns = holder.store?.getState().columns;
      if (pushed === null || !columns) return rows as TData[];
      const byId = new Map(columns.map((column) => [column.id, column] as const));
      return rows.map((row, index) => {
        const cells = row === undefined ? undefined : pushed.get(idOf(row, start + index));
        if (!cells) return row;
        let next = row;
        for (const [columnId, value] of cells) {
          const column = byId.get(columnId);
          if (column) next = setCellValue(next, column as never, value as never);
        }
        return next;
      });
    },
    [holder],
  );
  return { plugins, protectedRows, savingRows, saveMark, savedSince, pruneSaves, overlayPushed, streamUpdateRow, setSettleListener, setSaveStartListener, setSavesSettledListener, setReshapeListener, forgetStructural, evictionProtected, acknowledge, unacknowledgedRows };
}

/**
 * The row a stream update writes onto the row that `data` holds now. A push made on a row that a block has replaced since carries
 * the whole row it was made on; writing only its cells keeps the old values of the other cells from coming back.
 * `applyChange` calls it with the current row, so it needs no pass of its own over the rows.
 */
export function rowOfStreamUpdate<TData>(change: DataChange<TData>, columns: readonly { id: string }[]) {
  if (change.source !== "stream") return undefined;
  const byId = new Map(columns.map((column) => [column.id, column] as const));
  return (op: Extract<DataChange<TData>["ops"][number], { type: "update" }>, current: TData): TData => {
    if (!op.cells || current === op.prev) return op.row;
    let row = current;
    for (const cell of op.cells) {
      const column = byId.get(cell.columnId);
      if (column) row = setCellValue(row, column as never, cell.value as never);
    }
    return row;
  };
}

/** Applies the rule to an incoming page: a deleted row is dropped, a protected row keeps its local value by id, and a protected row the page lacks stays at the end. */
export function keepProtectedRows<TData>(
  incoming: readonly TData[],
  current: readonly TData[],
  guarded: ProtectedRows,
  deleted: ReadonlySet<string>,
  keepMissing: boolean,
  idOf: (row: TData, index: number) => string,
): TData[] {
  if (guarded === null && deleted.size === 0) return incoming as TData[];
  const local = new Map<string, TData>();
  current.forEach((row, index) => {
    const id = idOf(row, index);
    if (guarded?.has(id)) local.set(id, row);
  });
  const placed = new Set<string>();
  const page: TData[] = [];
  incoming.forEach((row, index) => {
    const id = idOf(row, index);
    if (deleted.has(id)) return;
    placed.add(id);
    page.push(local.get(id) ?? row);
  });
  if (keepMissing) for (const [id, row] of local) if (!placed.has(id) && !deleted.has(id)) page.push(row);
  return page;
}

/** Notes the rows a change deleted, and forgets a row that a change inserted again. */
export function trackDeletes(deleted: Set<string>, change: { ops: readonly { type: string; rowId: string }[] }) {
  for (const op of (change.ops as typeof change.ops | undefined) ?? []) {
    if (op.type === "delete") deleted.add(op.rowId);
    else if (op.type === "insert") deleted.delete(op.rowId);
  }
}

/** Drops the rows whose delete is no longer pending. */
export function pruneIds(ids: Set<string>, stillSaving: ProtectedRows) {
  for (const id of ids) if (!stillSaving?.has(id)) ids.delete(id);
}

/** The union of two protected sets; either may be `null`. */
export function unionIds(a: ProtectedRows, b: ProtectedRows): ProtectedRows {
  if (a === null) return b;
  if (b === null || a === b) return a;
  return new Set([...a, ...b]);
}

export type GuardedBlock<TData> = { start: number; rows: readonly (TData | undefined)[]; guard: ProtectedRows };

/** Moves the guarded rows in the given index ranges into `into`, for the block that brings their ids back. */
export function stashGuardedRows<TData>(
  rows: readonly (TData | undefined)[],
  ranges: readonly { start: number; end: number }[],
  guarded: ReadonlySet<string>,
  into: Map<string, TData>,
  idOf: (row: TData, index: number) => string,
  orphans: Map<string, { row: TData; slot: number }>,
) {
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && guarded.has(idOf(row, index))) {
        into.set(idOf(row, index), row);
        orphans.set(idOf(row, index), { row, slot: index });
      }
    }
  }
}

function findSlot<TData>(rows: readonly (TData | undefined)[], ranges: readonly { start: number; end: number }[], id: string, idOf: (row: TData, index: number) => string, near: number): number {
  for (const index of [near - 1, near + 1]) {
    const row = rows[index];
    if (row !== undefined && idOf(row, index) === id) return index;
  }
  for (const { start, end } of ranges) {
    for (let index = start; index < Math.min(end, rows.length); index++) {
      const row = rows[index];
      if (row !== undefined && idOf(row, index) === id) return index;
    }
  }
  return -1;
}

/**
 * Writes blocks into a copy of `prev`. A block guards the ids it was requested with plus the `live` ones: such a row keeps its
 * local value and appears once, at the index the answer gives it. `displaced` holds a guarded row that an earlier block overwrote,
 * for the block that brings its id back. `cleared` lists the slots left empty because a row moved away from them.
 */
export function writeBlocks<TData>(
  prev: readonly (TData | undefined)[],
  blocks: readonly GuardedBlock<TData>[],
  live: ProtectedRows,
  displaced: Map<string, TData>,
  ranges: readonly { start: number; end: number }[],
  idOf: (row: TData, index: number) => string,
  memory: { orphans: Map<string, { row: TData; slot: number }>; carried: Set<string> },
  final = false,
): { rows: (TData | undefined)[]; cleared: number[]; restored: number[] } {
  const next = prev.slice();
  const emptied: number[] = [];
  const restored: number[] = [];
  const { carried, orphans: overwritten } = memory;
  const stillProtected = new Set<string>();
  for (const { start, rows, guard } of blocks) {
    const guarded = unionIds(guard, live);
    if (guarded !== null) for (const id of guarded) stillProtected.add(id);
    for (let i = 0; i < rows.length && start + i < next.length; i++) {
      const slot = start + i;
      const incoming = rows[i];
      if (guarded === null) {
        next[slot] = incoming;
        continue;
      }
      const occupant = next[slot];
      const occupantId = occupant === undefined ? undefined : idOf(occupant, slot);
      const incomingId = incoming === undefined ? undefined : idOf(incoming, slot);
      if (incomingId !== undefined) carried.add(incomingId);
      if (incomingId !== undefined && guarded.has(incomingId)) {
        if (occupantId === incomingId) continue;
        if (occupantId !== undefined && guarded.has(occupantId)) {
          displaced.set(occupantId, occupant as TData);
          overwritten.set(occupantId, { row: occupant as TData, slot });
        }
        const from = findSlot(next, ranges, incomingId, idOf, slot);
        const local = from >= 0 ? next[from] : displaced.get(incomingId);
        next[slot] = local ?? incoming;
        if (local !== undefined && from >= 0) {
          next[from] = undefined;
          emptied.push(from);
        }
        continue;
      }
      if (occupantId !== undefined && guarded.has(occupantId)) {
        displaced.set(occupantId, occupant as TData);
        overwritten.set(occupantId, { row: occupant as TData, slot });
      }
      next[slot] = incoming;
    }
  }
  // Nothing else is loading: a protected row that the answer does not carry (a pending insert) returns to its own slot when no answer row sits there.
  if (final) {
    for (const [id, { row, slot }] of overwritten) {
      if (carried.has(id) || !stillProtected.has(id) || slot >= next.length || next[slot] !== undefined) continue;
      next[slot] = row;
      restored.push(slot);
    }
  }
  return { rows: next, cleared: emptied.filter((slot) => next[slot] === undefined), restored };
}

import type { FilterGroup, FilterNode, FilterOperator, FilterOperatorInput, FilterSpec, ServerSpec, SortSpec } from "@/registry/default/components/data-grid/data-grid";
import type { GroupKey, GroupPathSegment, ServerAggregate } from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_FILTER_GROUP_DEPTH, MAX_SPEC_SEARCH_LENGTH, MAX_SPEC_SORTS, filterOperatorInput, isBuiltInOperator } from "@/registry/default/components/data-grid/data-grid-sdk";

/** What a request may do with one column. Every field is optional. */
export type ServerSpecColumnRules = {
  /** `false` rejects a sort on the column. Default `true`. */
  sortable?: boolean;
  /** `false` rejects a filter on the column. Default `true`. */
  filterable?: boolean;
  /** Allowed operators. Default: every built-in operator. A custom operator in `customOperators` is allowed whether or not this list names it. */
  operators?: readonly FilterOperator[];
  /** Custom operators the column accepts, with the value shape of each. */
  customOperators?: Readonly<Record<string, FilterOperatorInput>>;
  /** `false` rejects `groupBy` on the column. Default `true`. */
  groupable?: boolean;
  /** `false` rejects an aggregate on the column. Default `true`. */
  aggregatable?: boolean;
};

/** Bounds that apply to the whole request. Every field is optional; a negative or non-finite value keeps the default. Groups nest at most 2 levels deep. */
export type ServerSpecLimits = {
  /** Most sort entries. Default 64. */
  maxSorts?: number;
  /** Most filter rows in the tree. Default 64. */
  maxFilters?: number;
  /** Most filter groups in the tree. Default 16. */
  maxGroups?: number;
  /** Longest text of one filter value, one list entry, or one range bound. Default 1000. */
  maxValueLength?: number;
  /** Most entries of an `isAnyOf` or `isNoneOf` list. Default 1000. */
  maxListLength?: number;
  /** Longest `searchText`. Default 500. */
  maxSearchLength?: number;
  /** Most `groupBy` columns. Default 4. */
  maxGroupLevels?: number;
  /** Longest group key of a group path. Default 1024. */
  maxGroupKeyLength?: number;
  /** Most `aggregates` entries. Default 32. */
  maxGroupAggregates?: number;
};

export type ParseServerSpecOptions = {
  /** The columns a request may name: a list of ids (no extra rules), or a map from id to its rules. */
  columns: readonly string[] | Readonly<Record<string, ServerSpecColumnRules>>;
  limits?: ServerSpecLimits;
};

/** Thrown by {@link parseServerSpec}. `path` names the offending part of the request, such as `filters[2].value`. */
export class ServerSpecError extends Error {
  readonly path: string;
  constructor(path: string, message: string) {
    super(`${path}: ${message}`);
    this.name = "ServerSpecError";
    this.path = path;
  }
}

const DEFAULT_LIMITS = { maxSorts: MAX_SPEC_SORTS, maxFilters: 64, maxGroups: 16, maxValueLength: 1000, maxListLength: 1000, maxSearchLength: MAX_SPEC_SEARCH_LENGTH, maxGroupLevels: 4, maxGroupKeyLength: 1024, maxGroupAggregates: 32 } satisfies Required<ServerSpecLimits>;

type Budget = { filters: number; groups: number };

type Raw = { sorts?: unknown; filters?: unknown; filterJoin?: unknown; searchText?: unknown; groupBy?: unknown; aggregates?: unknown; columnId?: unknown; direction?: unknown; join?: unknown; operator?: unknown; value?: unknown; matchCase?: unknown };

const isRecord = (value: unknown): value is Raw => typeof value === "object" && value !== null && !Array.isArray(value);

/**
 * Turns an untrusted request body into a bounded, typed {@link ServerSpec}, or throws {@link ServerSpecError}. It checks the
 * shape, the column ids, the operators, the value shapes, and the size of the tree, and drops every key it does not know.
 * It does not build a query: map the result to your query layer.
 *
 * @example
 * const spec = parseServerSpec(body.spec, { columns: ["name", "status", "age"] });
 */
export function parseServerSpec(input: unknown, options: ParseServerSpecOptions): ServerSpec {
  const limits = limitsOf(options);
  const rules = columnRules(options.columns);
  if (!isRecord(input)) throw new ServerSpecError("spec", "must be an object");
  const spec: ServerSpec = {
    sorts: parseSorts(input.sorts, rules, limits),
    filters: parseFilters(input.filters, rules, limits),
    searchText: parseSearch(input.searchText, limits),
  };
  const filterJoin = parseFilterJoin(input.filterJoin);
  const groupBy = parseGroupBy(input.groupBy, rules, limits);
  const aggregates = parseAggregates(input.aggregates, groupBy.length > 0, rules, limits);
  return { ...spec, ...(filterJoin === "or" ? { filterJoin } : null), ...(groupBy.length > 0 ? { groupBy } : null), ...(aggregates.length > 0 ? { aggregates } : null) };
}

/**
 * Reads the `groupPath` and `childKind` of a grouped request against its parsed `spec`, or throws {@link ServerSpecError}. The path follows
 * `spec.groupBy` in order and is not longer; the kind is `"groups"` while the path is shorter than `groupBy`, else `"rows"`.
 * A spec without `groupBy` accepts an empty path only.
 *
 * @example
 * const { groupPath, childKind } = parseGroupPath(body, spec);
 */
export function parseGroupPath(input: unknown, spec: ServerSpec, options: { limits?: ServerSpecLimits } = {}): { groupPath: GroupPathSegment[]; childKind: "groups" | "rows" } {
  const groupBy = spec.groupBy ?? [];
  const limits = limitsOf(options);
  const body = isRecord(input) ? (input as { groupPath?: unknown; childKind?: unknown }) : {};
  const rawPath = body.groupPath ?? [];
  if (!Array.isArray(rawPath)) throw new ServerSpecError("groupPath", "must be an array");
  if (rawPath.length > groupBy.length) throw new ServerSpecError("groupPath", "is longer than groupBy");
  const groupPath = rawPath.map((segment: unknown, index): GroupPathSegment => {
    const path = `groupPath[${index}]`;
    if (!isRecord(segment)) throw new ServerSpecError(path, "must be an object");
    const raw = segment as { columnId?: unknown; key?: unknown };
    if (raw.columnId !== groupBy[index]) throw new ServerSpecError(`${path}.columnId`, "must follow groupBy in order");
    return { columnId: groupBy[index]!, key: groupKey(raw.key, `${path}.key`, limits) };
  });
  const childKind = groupPath.length < groupBy.length ? "groups" : "rows";
  if (body.childKind !== undefined && body.childKind !== childKind) throw new ServerSpecError("childKind", `must be "${childKind}" for a path of ${groupPath.length} of ${groupBy.length} levels`);
  return { groupPath, childKind };
}

function parseFilterJoin(value: unknown): "and" | "or" {
  if (value === undefined || value === "and" || value === "or") return value ?? "and";
  throw new ServerSpecError("filterJoin", 'must be "and" or "or"');
}

function limitsOf(options: { limits?: ServerSpecLimits }): Required<ServerSpecLimits> {
  const limits = { ...DEFAULT_LIMITS };
  for (const key of Object.keys(DEFAULT_LIMITS) as (keyof ServerSpecLimits)[]) {
    const wanted = options.limits?.[key];
    if (wanted !== undefined && Number.isFinite(wanted) && wanted >= 0) limits[key] = wanted;
  }
  return limits;
}

function groupKey(value: unknown, path: string, limits: Required<ServerSpecLimits>): GroupKey {
  if (value === null || typeof value === "boolean" || (typeof value === "number" && Number.isFinite(value))) return value;
  if (typeof value !== "string") throw new ServerSpecError(path, "must be a string, a finite number, a boolean, or null");
  if (value.length > limits.maxGroupKeyLength) throw new ServerSpecError(path, `is longer than ${limits.maxGroupKeyLength}`);
  return value;
}

function parseGroupBy(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): string[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new ServerSpecError("groupBy", "must be an array");
  if (value.length > limits.maxGroupLevels) throw new ServerSpecError("groupBy", `holds more than ${limits.maxGroupLevels} columns`);
  const seen = new Set<string>();
  return value.map((entry: unknown, index) => {
    const path = `groupBy[${index}]`;
    const columnId = knownColumn(entry, rules, path);
    if (rules.get(columnId)!.groupable === false) throw new ServerSpecError(path, `"${columnId}" cannot be grouped`);
    if (seen.has(columnId)) throw new ServerSpecError(path, `repeats "${columnId}"`);
    seen.add(columnId);
    return columnId;
  });
}

const REDUCERS: readonly string[] = ["sum", "avg", "min", "max", "count"];

function parseAggregates(value: unknown, grouped: boolean, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): ServerAggregate[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new ServerSpecError("aggregates", "must be an array");
  if (value.length === 0) return [];
  if (!grouped) throw new ServerSpecError("aggregates", "needs groupBy");
  if (value.length > limits.maxGroupAggregates) throw new ServerSpecError("aggregates", `holds more than ${limits.maxGroupAggregates} entries`);
  const seen = new Set<string>();
  return value.map((entry: unknown, index) => {
    const path = `aggregates[${index}]`;
    if (!isRecord(entry)) throw new ServerSpecError(path, "must be an object");
    const raw = entry as { columnId?: unknown; reducer?: unknown };
    const columnId = knownColumn(raw.columnId, rules, `${path}.columnId`);
    if (rules.get(columnId)!.aggregatable === false) throw new ServerSpecError(`${path}.columnId`, `"${columnId}" cannot be aggregated`);
    if (seen.has(columnId)) throw new ServerSpecError(`${path}.columnId`, `repeats "${columnId}"`);
    seen.add(columnId);
    if (typeof raw.reducer !== "string" || !REDUCERS.includes(raw.reducer)) throw new ServerSpecError(`${path}.reducer`, `must be one of ${REDUCERS.join(", ")}`);
    return { columnId, reducer: raw.reducer as ServerAggregate["reducer"] };
  });
}

function columnRules(columns: ParseServerSpecOptions["columns"]): ReadonlyMap<string, ServerSpecColumnRules> {
  if (Array.isArray(columns)) return new Map((columns as readonly string[]).map((id) => [id, {}]));
  return new Map(Object.entries(columns as Readonly<Record<string, ServerSpecColumnRules>>));
}

function parseSearch(value: unknown, limits: Required<ServerSpecLimits>): string {
  if (value === undefined || value === null) return "";
  if (typeof value !== "string") throw new ServerSpecError("searchText", "must be a string");
  if (value.length > limits.maxSearchLength) throw new ServerSpecError("searchText", `is longer than ${limits.maxSearchLength}`);
  return value;
}

function parseSorts(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): SortSpec[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) throw new ServerSpecError("sorts", "must be an array");
  if (value.length > limits.maxSorts) throw new ServerSpecError("sorts", `holds more than ${limits.maxSorts} entries`);
  return value.map((entry: unknown, index) => {
    const path = `sorts[${index}]`;
    if (!isRecord(entry)) throw new ServerSpecError(path, "must be an object");
    const columnId = knownColumn(entry.columnId, rules, `${path}.columnId`);
    if (rules.get(columnId)!.sortable === false) throw new ServerSpecError(`${path}.columnId`, `"${columnId}" cannot be sorted`);
    if (entry.direction !== "asc" && entry.direction !== "desc") throw new ServerSpecError(`${path}.direction`, 'must be "asc" or "desc"');
    return { columnId, direction: entry.direction };
  });
}

function knownColumn(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, path: string): string {
  if (typeof value !== "string" || !rules.has(value)) throw new ServerSpecError(path, "names an unknown column");
  return value;
}

function parseFilters(value: unknown, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>): FilterNode[] {
  if (value === undefined || value === null) return [];
  const budget: Budget = { filters: 0, groups: 0 };
  return parseNodes(value, "filters", 0, rules, limits, budget);
}

function parseNodes(value: unknown, path: string, depth: number, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterNode[] {
  if (!Array.isArray(value)) throw new ServerSpecError(path, "must be an array");
  return value.map((node: unknown, index) => {
    const nodePath = `${path}[${index}]`;
    if (!isRecord(node)) throw new ServerSpecError(nodePath, "must be an object");
    if (Object.hasOwn(node, "filters")) return parseGroup(node, nodePath, depth + 1, rules, limits, budget);
    return parseRow(node, nodePath, rules, limits, budget);
  });
}

function parseGroup(node: Raw, path: string, depth: number, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterGroup {
  if (depth > MAX_FILTER_GROUP_DEPTH) throw new ServerSpecError(path, `nests groups deeper than ${MAX_FILTER_GROUP_DEPTH}`);
  budget.groups += 1;
  if (budget.groups > limits.maxGroups) throw new ServerSpecError(path, `holds more than ${limits.maxGroups} groups`);
  if (node.join !== "and" && node.join !== "or") throw new ServerSpecError(`${path}.join`, 'must be "and" or "or"');
  return { join: node.join, filters: parseNodes(node.filters, `${path}.filters`, depth, rules, limits, budget) };
}

function parseRow(node: Raw, path: string, rules: ReadonlyMap<string, ServerSpecColumnRules>, limits: Required<ServerSpecLimits>, budget: Budget): FilterSpec {
  budget.filters += 1;
  if (budget.filters > limits.maxFilters) throw new ServerSpecError(path, `holds more than ${limits.maxFilters} filters`);
  const columnId = knownColumn(node.columnId, rules, `${path}.columnId`);
  const column = rules.get(columnId)!;
  if (column.filterable === false) throw new ServerSpecError(`${path}.columnId`, `"${columnId}" cannot be filtered`);
  if (typeof node.operator !== "string") throw new ServerSpecError(`${path}.operator`, "must be a string");
  const operator = node.operator;
  const custom = column.customOperators && Object.hasOwn(column.customOperators, operator) ? column.customOperators[operator] : undefined;
  const allowed = column.operators ? column.operators.includes(operator) || custom !== undefined : isBuiltInOperator(operator) || custom !== undefined;
  if (!allowed) throw new ServerSpecError(`${path}.operator`, `"${operator.slice(0, 40)}" is not allowed on "${columnId.slice(0, 40)}"`);
  const input = custom ?? filterOperatorInput(operator);
  const value = parseValue(node.value, input, `${path}.value`, limits);
  const row: FilterSpec = value === undefined ? { columnId, operator } : { columnId, operator, value };
  return node.matchCase === true ? { ...row, matchCase: true } : row;
}

function text(value: unknown, path: string, limits: Required<ServerSpecLimits>): string {
  if (typeof value !== "string") throw new ServerSpecError(path, "must be a string");
  if (value.length > limits.maxValueLength) throw new ServerSpecError(path, `is longer than ${limits.maxValueLength}`);
  return value;
}

function parseValue(value: unknown, input: FilterOperatorInput, path: string, limits: Required<ServerSpecLimits>): FilterSpec["value"] {
  if (input === "none") return undefined;
  if (input === "single") return text(value, path, limits);
  if (!Array.isArray(value)) throw new ServerSpecError(path, "must be an array");
  if (input === "range") {
    if (value.length !== 2) throw new ServerSpecError(path, "must hold two bounds");
    return [text(value[0], `${path}[0]`, limits), text(value[1], `${path}[1]`, limits)];
  }
  if (value.length > limits.maxListLength) throw new ServerSpecError(path, `holds more than ${limits.maxListLength} entries`);
  return value.map((entry: unknown, index) => text(entry, `${path}[${index}]`, limits));
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useRef } from "react";
import type { DataChange, SaveAck, SaveContext } from "@/registry/default/components/data-grid/data-grid";

/** What `refreshAfterSave` sees when it decides: the saves that settled since the last refresh. */
export type SaveRefreshReport = {
  /** Saves the server accepted (`onSave` returned a promise that resolved with nothing or without `rejected`). */
  saved: number;
  /** Saves that resolved with `{ rejected }`. */
  rejected: number;
  /** Saves whose `onSave` threw or whose promise rejected. */
  failed: number;
  /** The changes of those saves, oldest first, at most 100, for a policy that decides per change. */
  changes: readonly DataChange<unknown>[];
  /** Saves still in flight when the decision runs; above 0 only when the 10 second wait forced it. */
  pending: number;
};

/**
 * When the hook fetches again after `onSave` settles.
 * - `"settled"`: once, after every save in flight has settled (or after 10 seconds, so one stuck save cannot stop the refresh). A burst of saves costs one request. After the 10 seconds, each save still in flight refreshes when it settles, until a new save starts a new wait.
 * - `"each"`: after saves settle, without waiting for the saves still in flight. Saves that settle in the same task share one refresh.
 * - `false`: never. Call `refresh()` yourself.
 * - a function: once after every save in flight has settled (or after the same 10 seconds), when it returns `true`. A throw counts as `false`.
 *
 * Only a promise from `onSave` counts as a save: a handler that returns nothing has not told the grid when the server has the change, so it never triggers a refresh (call `refresh()` yourself). A refresh needs at least one save the server answered; saves that all threw skip it.
 */
export type SaveRefreshPolicy = false | "each" | "settled" | ((report: SaveRefreshReport) => boolean);

export type SaveRefreshOptions<TData> = {
  /** Saves a change. Spread through `gridProps.onSave`; it behaves as the `DataGridProvider` prop of the same name. */
  onSave?: (change: DataChange<TData>, ctx: SaveContext) => void | Promise<SaveAck<TData>>;
  /** Default `"settled"` while `onSave` is set. */
  refreshAfterSave?: SaveRefreshPolicy;
};

const isThenable = (value: unknown): value is PromiseLike<unknown> => typeof (value as PromiseLike<unknown> | null)?.then === "function";

/** Longest wait for saves in flight before the `"settled"` policies decide anyway, so one save that never settles cannot stop every later refresh. */
export const SAVE_REFRESH_MAX_WAIT_MS = 10_000;

type SaveFn<TData> = (change: DataChange<TData>, ctx: SaveContext) => void | Promise<SaveAck<TData>>;

/**
 * Wraps the caller's `onSave` so the hook refreshes after saves settle by the caller's policy. `onSave` is `undefined` without an
 * `onSave` option, so spreading `gridProps` never overrides a provider `onSave` of your own. `wrapSave` tracks a provider `onSave` the same way.
 */
export function useSaveRefresh<TData>(options: SaveRefreshOptions<TData> = {}, refresh: () => void): { onSave: SaveFn<TData> | undefined; wrapSave: (save: SaveFn<TData>) => SaveFn<TData> } {
  const live = useRef({ options, refresh });
  useLayoutEffect(() => {
    live.current = { options, refresh };
  });
  const state = useRef({ inflight: 0, counts: { saved: 0, rejected: 0, failed: 0 }, changes: [] as DataChange<unknown>[], scheduled: false, settleTimer: null as ReturnType<typeof setTimeout> | null, mounted: true, waitExpired: false, maxWait: null as ReturnType<typeof setTimeout> | null });
  useEffect(() => {
    state.current.mounted = true;
    return () => {
      const current = state.current;
      current.mounted = false;
      if (current.maxWait !== null) clearTimeout(current.maxWait);
      if (current.settleTimer !== null) clearTimeout(current.settleTimer);
      current.maxWait = null;
      current.settleTimer = null;
      current.scheduled = false;
    };
  }, []);

  const decide = useCallback((force = false) => {
    const current = state.current;
    current.scheduled = false;
    current.settleTimer = null;
    if (current.maxWait !== null && (force || current.inflight === 0)) {
      clearTimeout(current.maxWait);
      current.maxWait = null;
    }
    if (!current.mounted) return;
    const policy = live.current.options.refreshAfterSave ?? "settled";
    if (policy === false) {
      current.counts = { saved: 0, rejected: 0, failed: 0 };
      current.changes = [];
      return;
    }
    if (policy !== "each" && current.inflight > 0 && !force) return;
    if (current.counts.saved + current.counts.rejected === 0) {
      current.counts = { saved: 0, rejected: 0, failed: 0 };
      current.changes = [];
      if (force) current.waitExpired = true;
      return;
    }
    current.waitExpired = (force || current.waitExpired) && current.inflight > 0;
    const report: SaveRefreshReport = { ...current.counts, changes: current.changes, pending: current.inflight };
    current.counts = { saved: 0, rejected: 0, failed: 0 };
    current.changes = [];
    if (typeof policy === "function") {
      let wanted = false;
      try {
        wanted = policy(report);
      } catch (error) {
        console.error("[data-grid-server] refreshAfterSave threw", error);
      }
      if (!wanted) return;
    }
    live.current.refresh();
  }, []);

  const settle = useCallback(
    (kind: "saved" | "rejected" | "failed", change: DataChange<TData>) => {
      const current = state.current;
      current.counts[kind] += 1;
      if (current.changes.length < 100) current.changes.push(change);
      if (current.scheduled) return;
      current.scheduled = true;
      current.settleTimer = setTimeout(() => decide(current.waitExpired), 0); // after the grid has settled the row, so the refresh sees it as saved
    },
    [decide],
  );

  const hasSave = options.onSave !== undefined;
  const track = useCallback(
    (run: SaveFn<TData>, change: DataChange<TData>, ctx: SaveContext): void | Promise<SaveAck<TData>> => {
      let result: void | Promise<SaveAck<TData>>;
      try {
        result = run(change, ctx);
      } catch (error) {
        settle("failed", change);
        throw error;
      }
      if (!isThenable(result)) return result;
      state.current.inflight += 1;
      if (state.current.maxWait === null) {
        state.current.waitExpired = false;
        state.current.maxWait = setTimeout(() => decide(true), SAVE_REFRESH_MAX_WAIT_MS);
      }
      return Promise.resolve(result).then(
        (ack) => {
          state.current.inflight -= 1;
          settle(ack && (ack.rejected?.length ?? 0) > 0 ? "rejected" : "saved", change);
          return ack;
        },
        (error: unknown) => {
          state.current.inflight -= 1;
          settle("failed", change);
          throw error;
        },
      );
    },
    [settle, decide],
  );
  const onSave = useCallback(
    (change: DataChange<TData>, ctx: SaveContext) => {
      const run = live.current.options.onSave;
      return run ? track(run, change, ctx) : undefined;
    },
    [track],
  );
  const wrapSave = useCallback((save: SaveFn<TData>): SaveFn<TData> => (change, ctx) => track(save, change, ctx), [track]);
  return { onSave: hasSave ? onSave : undefined, wrapSave };
}

import type { RowRange, ServerSpec } from "@/registry/default/components/data-grid/data-grid";
import type { GroupPathSegment } from "@/registry/default/components/data-grid/data-grid-sdk";
import type { ServerGroupsAnswer } from "./read-groups-answer";

/** Largest row count the server contract accepts; a bigger count clamps to it. */
export const MAX_ROW_COUNT = 10_000_000;

/** Why a request runs: `"load"` for a window, page, or spec; `"refresh"` for `refresh()`, a timed refresh, or a reshape; `"save"` after a save settled; `"retry"` for `retry()`. */
export type FetchReason = "load" | "refresh" | "save" | "retry";

/** What `fetchRows` receives in every mode. */
export type ServerRowsRequest<TCursor = never> = {
  /** The sort, filter, and search of this request. */
  spec: ServerSpec;
  /** Index of the first requested row in the result. */
  start: number;
  /** One past the last requested row; `end - start` is the limit. */
  end: number;
  /** Cursor sources: the `nextCursor` of the block or page before; `undefined` for the first one and for every other source. */
  cursor: TCursor | undefined;
  /** Why this request runs. The hook sends it to nobody: read it to bypass a cache on a refresh. */
  reason: FetchReason;
  /** Aborted when a newer request replaces this one, when a scroll-mode block leaves the rendered rows by more than `overscan` plus one block, on a spec change, and on unmount. */
  signal: AbortSignal;
  /** Only while `spec.groupBy` is not empty: the group whose children this request reads, outermost first; `[]` is the top level. */
  groupPath?: readonly GroupPathSegment[];
  /** Only while `spec.groupBy` is not empty: `"groups"` while `groupPath` is shorter than `groupBy`, else `"rows"`. */
  childKind?: "groups" | "rows";
};

/** Pages mode adds the page address; `start` is `(page - 1) * pageSize`. */
export type ServerRowsPageRequest<TCursor = never> = ServerRowsRequest<TCursor> & {
  /** 1-based page. */
  page: number;
  pageSize: number;
};

/** What `fetchRows` resolves with in every mode. */
export type ServerRowsAnswer<TData, TCursor = never> = {
  /** At most `end - start` rows, in order from `start`; extra rows are dropped with a development warning. A repeated row id keeps its first row; the later copy leaves its slot empty in random-access scroll mode (a skeleton row), and a sequential source and pages mode drop it. Make the sort total. */
  rows: TData[];
  /** Row count of the result. Omitted keeps the last known count; `null` declares it unknown. A value that is not a non-negative integer reads as `null` (dev-warned); a count above 10,000,000 clamps to it. */
  totalRowCount?: number | null;
  /** Rows exist after this block. Default: the block came back full. Random access and pages mode ignore it when a count is known; a sequential source ends on `false` also with a count. */
  hasMore?: boolean;
  /** Cursor sources: passed back as `cursor`. `null` ends the source. */
  nextCursor?: TCursor | null;
};

/** What `fetchRows` of a grouped scroll source resolves with: groups for `childKind: "groups"`, rows for `"rows"`. */
export type ServerFetchAnswer<TData, TCursor = never> = ServerRowsAnswer<TData, TCursor> | ServerGroupsAnswer;

/** An answer after validation. */
export type ReadAnswer<TData, TCursor = never> = {
  /** The answer's rows in order; a later copy of a repeated id is `undefined`, so the other rows keep their positions. */
  rows: (TData | undefined)[];
  /** `undefined` keeps the last known count. */
  totalRowCount: number | null | undefined;
  hasMore: boolean;
  /** The `hasMore` the answer carried, if any. */
  hasMoreSent: boolean | undefined;
  nextCursor: TCursor | null | undefined;
};

/**
 * Validates an untrusted answer: `rows` must be an array and is cut to the requested size, `totalRowCount` must be a
 * non-negative safe integer (else unknown) and clamps to {@link MAX_ROW_COUNT}. Throws when the answer has no rows array.
 */
export function readAnswer<TData, TCursor = never>(
  answer: unknown,
  range: RowRange,
  warn: (kind: string, message: string) => void,
  idOf?: (row: TData, index: number) => string,
): ReadAnswer<TData, TCursor> {
  const raw = answer as Partial<ServerRowsAnswer<TData, TCursor>> | null | undefined;
  if (!Array.isArray(raw?.rows)) throw new TypeError("fetchRows of useDataGridServerRows must resolve with { rows: TData[] }");
  const limit = range.end - range.start;
  let rows: (TData | undefined)[] = raw.rows;
  if (rows.length > limit) {
    warn("long", `fetchRows returned ${rows.length} rows for a request of ${limit}; only the first ${limit} are used`);
    rows = rows.slice(0, limit);
  }
  const legacy = raw as { total?: unknown; hasNextPage?: unknown };
  if (("total" in legacy && !("totalRowCount" in raw)) || "hasNextPage" in legacy) {
    warn("legacy", "the answer of fetchRows uses `total` or `hasNextPage`; rename them to `totalRowCount` and `hasMore`");
  }
  let totalRowCount: number | null | undefined;
  if (raw.totalRowCount === undefined) totalRowCount = undefined;
  else if (raw.totalRowCount === null) totalRowCount = null;
  else if (typeof raw.totalRowCount === "number" && Number.isSafeInteger(raw.totalRowCount) && raw.totalRowCount >= 0) {
    totalRowCount = Math.min(raw.totalRowCount, MAX_ROW_COUNT);
    if (totalRowCount !== raw.totalRowCount) warn("count", `totalRowCount ${raw.totalRowCount} is above ${MAX_ROW_COUNT}; using ${MAX_ROW_COUNT}`);
  } else {
    totalRowCount = null;
    warn("count", "totalRowCount must be a non-negative integer or null; treating the count as unknown");
  }
  const full = rows.length === limit;
  if (idOf) rows = firstCopies(rows as TData[], idOf, range.start, warn);
  return {
    rows,
    totalRowCount,
    hasMore: typeof raw.hasMore === "boolean" ? raw.hasMore : full,
    hasMoreSent: typeof raw.hasMore === "boolean" ? raw.hasMore : undefined,
    nextCursor: raw.nextCursor,
  };
}

/** Keeps the first row of each id and blanks the later copies, so one answer never puts the same id twice into the grid. */
function firstCopies<TData>(rows: TData[], idOf: (row: TData, index: number) => string, start: number, warn: (kind: string, message: string) => void): (TData | undefined)[] {
  const seen = new Set<string>();
  let repeated = false;
  const kept = rows.map((row, index) => {
    const id = idOf(row, start + index);
    if (seen.has(id)) {
      repeated = true;
      return undefined;
    }
    seen.add(id);
    return row;
  });
  if (repeated) warn("duplicate", "fetchRows returned a duplicate row id; only the first row of each id is used, so make the sort total (add the row id as a last sort key)");
  return kept;
}

/** Options after the hook filled in the default `getRowId`. */
export type WithRowId<TOptions, TData> = TOptions & { getRowId: (row: TData, index: number) => string };

import type { RowRange } from "@/registry/default/components/data-grid/data-grid";
import { groupKeyText, type GroupKey, type GroupPathSegment } from "@/registry/default/components/data-grid/data-grid-sdk";
import { MAX_ROW_COUNT } from "./read-answer";

/** What a request asks of the server while the grid is grouped: the children of one group. */
export type ServerChildKind = "groups" | "rows";

/** The group a request reads the children of, outermost first; `[]` is the top level. */
export type ServerGroupPath = readonly GroupPathSegment[];

/** One group row of a {@link ServerGroupsAnswer}. */
export type ServerGroupRow = {
  /** The stored value the group shares. `null` is the empty group; the server merges `null` and `""` into it. */
  key: GroupKey;
  /** Display text of the key. Default: the text of the column's cell type. Cut to 1,024 characters. */
  label?: string;
  /** Direct children: groups of the next level, or rows in a group of the last level. */
  childCount: number;
  /** Rows of the result under this group; equals `childCount` on the last level. */
  totalRowCount: number;
  /** One value per requested aggregate column id: a finite number, or `null` when no value counted. */
  aggregates?: Readonly<Record<string, unknown>>;
};

/** What `fetchRows` resolves with for a request of `childKind: "groups"`. */
export type ServerGroupsAnswer = {
  /** At most `end - start` group rows of one level, in order from `start`. */
  groups: readonly ServerGroupRow[];
  /** Group rows under the parent. */
  groupCount: number;
  /** Top level: the row count of the result. Required there. */
  totalRowCount?: number;
};

/** A groups answer after validation. */
export type ReadGroupsAnswer = {
  groups: ServerGroupRow[];
  groupCount: number;
  totalRowCount: number | undefined;
};

/** Longest group key and label the grid accepts. */
export const MAX_GROUP_TEXT_LENGTH = 1024;

const RESERVED_ROW_ID_PREFIXES = ["__group:", "__pinned-", "__lazy-unloaded-"] as const;

type Warn = (kind: string, message: string) => void;

const isCount = (value: unknown): value is number => typeof value === "number" && Number.isSafeInteger(value) && value >= 0;

function count(value: unknown, field: string, warn: Warn): number {
  if (!isCount(value)) throw new TypeError(`fetchRows answered ${field} that is not a non-negative integer`);
  if (value <= MAX_ROW_COUNT) return value;
  warn("count", `${field} ${value} is above ${MAX_ROW_COUNT}; using ${MAX_ROW_COUNT}`);
  return MAX_ROW_COUNT;
}

function readKey(key: unknown, field: string): GroupKey {
  if (key === null || typeof key === "boolean" || (typeof key === "number" && Number.isFinite(key))) return key;
  if (typeof key === "string" && key.length <= MAX_GROUP_TEXT_LENGTH) return key;
  throw new TypeError(`fetchRows answered ${field} that is not a string of at most ${MAX_GROUP_TEXT_LENGTH} characters, a finite number, a boolean, or null`);
}

function readAggregates(raw: unknown, ids: readonly string[], field: string, warn: Warn): Record<string, unknown> | undefined {
  if (typeof raw !== "object" || raw === null) return undefined;
  const out = Object.create(null) as Record<string, unknown>;
  for (const id of ids) {
    if (!Object.hasOwn(raw, id)) continue;
    const value = (raw as Record<string, unknown>)[id];
    if (typeof value === "number" && Number.isFinite(value)) out[id] = value;
    else {
      out[id] = null;
      if (value !== null) warn(`aggregate ${id}`, `${field}.aggregates.${id} must be a finite number or null; showing null`);
    }
  }
  return out;
}

/**
 * Validates an untrusted groups answer. It cuts `groups` to the requested size, bounds keys, labels, counts, and aggregates,
 * and reads only the aggregate ids that the request named. Throws a `TypeError` that names the group and the field when the
 * answer has no `groups` array, a key is invalid or repeated (`1` and `"1"` repeat), a count is invalid, or the top level lacks `totalRowCount`.
 */
export function readGroupsAnswer(answer: unknown, range: RowRange, options: { topLevel: boolean; aggregateIds: readonly string[] }, warn: Warn): ReadGroupsAnswer {
  const raw = answer as { groups?: unknown; groupCount?: unknown; totalRowCount?: unknown; rows?: unknown } | null | undefined;
  if (!Array.isArray(raw?.groups)) {
    const kind = Array.isArray(raw?.rows) ? " (it answered rows)" : "";
    throw new TypeError(`fetchRows must resolve with { groups, groupCount } for childKind "groups"${kind}`);
  }
  const limit = range.end - range.start;
  let list: unknown[] = raw.groups;
  if (list.length > limit) {
    warn("long", `fetchRows returned ${list.length} groups for a request of ${limit}; only the first ${limit} are used`);
    list = list.slice(0, limit);
  }
  const seen = new Set<string>();
  const groups = list.map((entry, index): ServerGroupRow => {
    const field = `groups[${index}]`;
    if (typeof entry !== "object" || entry === null) throw new TypeError(`fetchRows answered ${field} that is not an object`);
    const item = entry as { key?: unknown; label?: unknown; childCount?: unknown; totalRowCount?: unknown; aggregates?: unknown };
    const key = readKey(item.key, `${field}.key`);
    const keyText = groupKeyText(key);
    if (seen.has(keyText)) throw new TypeError(`fetchRows answered the key ${JSON.stringify(keyText.slice(0, 40))} twice (${field}.key); null and "" are one group, and 1 and "1" are one group`);
    seen.add(keyText);
    let label: string | undefined;
    if (typeof item.label === "string") {
      label = item.label.slice(0, MAX_GROUP_TEXT_LENGTH);
      if (label.length !== item.label.length) warn("label", `${field}.label is longer than ${MAX_GROUP_TEXT_LENGTH}; cut`);
    }
    const aggregates = readAggregates(item.aggregates, options.aggregateIds, field, warn);
    return {
      key,
      ...(label === undefined ? null : { label }),
      childCount: count(item.childCount, `${field}.childCount`, warn),
      totalRowCount: count(item.totalRowCount, `${field}.totalRowCount`, warn),
      ...(aggregates ? { aggregates } : null),
    };
  });
  const groupCount = count(raw.groupCount, "groupCount", warn);
  if (options.topLevel && raw.totalRowCount === undefined) throw new TypeError("fetchRows must answer totalRowCount with the top level of groups");
  return { groups, groupCount, totalRowCount: raw.totalRowCount === undefined ? undefined : count(raw.totalRowCount, "totalRowCount", warn) };
}

/** Throws when a row id starts with a prefix the grid reserves for group rows, pinned rows, and unloaded rows. */
export function assertRowIdsNotReserved(ids: Iterable<string>): void {
  for (const id of ids) {
    if (RESERVED_ROW_ID_PREFIXES.some((prefix) => id.startsWith(prefix))) throw new TypeError(`fetchRows returned the row id ${JSON.stringify(id.slice(0, 40))}, which starts with a prefix the grid reserves (${RESERVED_ROW_ID_PREFIXES.join(", ")})`);
  }
}

"use client";

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import type { DataGridPlugin, FilterNode, ServerSpec, SortSpec } from "@/registry/default/components/data-grid/data-grid";
import { isDev, registerServerWiring } from "@/registry/default/components/data-grid/data-grid-sdk";
import { DEFAULT_RESHAPE_DELAY, MIN_RESHAPE_DELAY, MIN_REVALIDATE_INTERVAL, readReshapeDelay, readRevalidateInterval } from "./fetch-hygiene";

/** The request state every mode of `useDataGridServerRows` returns. */
export type DataSourceState = {
  /** `"error"` wins over `"loading"`. */
  status: "loading" | "error" | "ready";
  /** A request of the current spec is in flight. */
  loading: boolean;
  /** The latest failure of the current spec, or `null`. */
  error: unknown;
  /** Repeats the failed requests. Does nothing without an error. */
  retry: () => void;
  /** Fetches what is in view again and keeps it on screen until the answer lands. The hook calls it after saves settle by `refreshAfterSave`. */
  refresh: () => void;
  /** Asks the server to place the rows again after a push: one `refresh()` on the next frame, or after `reshapeDelayMs`. Calls in one frame join. */
  reshape: () => void;
};

/** Runs `callback` on the next animation frame, or after 16 ms where there is none. Returns the cancel. */
export function scheduleFrame(callback: () => void): () => void {
  if (typeof requestAnimationFrame === "function") {
    const id = requestAnimationFrame(callback);
    return () => cancelAnimationFrame(id);
  }
  const id = setTimeout(callback, 16);
  return () => clearTimeout(id);
}

const EMPTY_SPEC: ServerSpec = { sorts: [], filters: [], searchText: "" };

/** Controlled or uncontrolled state with a stable setter that always calls the latest `onChange`. */
export function useControlled<T>(controlled: T | undefined, initial: () => T, onChange: ((next: T) => void) | undefined) {
  const [inner, setInner] = useState(initial);
  const latest = useRef({ controlled, onChange });
  useLayoutEffect(() => {
    latest.current = { controlled, onChange };
  });
  const set = useCallback((next: T) => {
    if (latest.current.controlled === undefined) setInner(next);
    latest.current.onChange?.(next);
  }, []);
  return [controlled ?? inner, set, setInner] as const;
}

/** Runs a consumer callback so that a throw cannot break the caller's bookkeeping. */
export function isolate(label: string, call: () => void) {
  try {
    call();
  } catch (error) {
    console.error(`[data-grid-server] ${label} threw`, error);
  }
}

/** The refresh guard first, then the consumer's plugins; the array keeps its identity while `own` does. */
export function useMountedPlugins(guard: readonly DataGridPlugin<unknown>[], own?: readonly DataGridPlugin<unknown>[]) {
  return useMemo(() => (own && own.length > 0 ? [...guard, ...own] : guard), [guard, own]);
}

export type ServerSpecOptions = {
  spec?: ServerSpec;
  defaultSpec?: Partial<ServerSpec> | (() => Partial<ServerSpec> | undefined);
  onSpecChange?: (spec: ServerSpec) => void;
};

/** The sort, filter, and search of a server source, with stable change handlers for the grid's controlled state. */
export function useServerSpec(source: ServerSpecOptions, afterChange: () => void, groups = false) {
  const lateSeed = typeof source.defaultSpec === "function" && source.spec === undefined ? source.defaultSpec : null;
  const [spec, setSpec, seedSpec] = useControlled<ServerSpec>(source.spec, () => specOf(lateSeed ? undefined : (source.defaultSpec as Partial<ServerSpec> | undefined), groups), source.onSpecChange);
  const [ready, setReady] = useState(lateSeed === null);
  const lateSeedRef = useRef(lateSeed);
  // A function seed runs after mount, on the client only, so the server render and the first client render match.
  useLayoutEffect(() => {
    const seed = lateSeedRef.current;
    if (seed) {
      let value: Partial<ServerSpec> | undefined;
      isolate("defaultSpec", () => (value = seed()));
      if (value) seedSpec(specOf(value, groups));
    }
    setReady(true);
  }, [seedSpec, groups]);
  const live = useRef({ spec, afterChange });
  useLayoutEffect(() => {
    live.current = { spec, afterChange };
  });
  const changeSpec = useCallback(
    (next: Partial<ServerSpec>) => {
      const merged = { ...live.current.spec, ...next };
      if (merged.groupBy?.length === 0) delete merged.groupBy;
      if (merged.filterJoin !== "or") delete merged.filterJoin;
      // Two changes in one effect (a URL restore) merge instead of overwriting each other.
      live.current.spec = merged;
      setSpec(merged);
      live.current.afterChange();
    },
    [setSpec],
  );
  const onSortChange = useCallback((sorts: SortSpec[]) => changeSpec({ sorts }), [changeSpec]);
  const onFilterChange = useCallback((filters: FilterNode[]) => changeSpec({ filters }), [changeSpec]);
  const onFilterJoinChange = useCallback((join: "and" | "or") => changeSpec({ filterJoin: join === "or" ? "or" : undefined }), [changeSpec]);
  const onSearchTextChange = useCallback((searchText: string) => changeSpec({ searchText }), [changeSpec]);
  const onGroupByChange = useCallback((groupBy: readonly string[]) => changeSpec({ groupBy }), [changeSpec]);
  return { spec, ready, onSortChange, onFilterChange, onFilterJoinChange, onSearchTextChange, onGroupByChange };
}

/** The result of {@link useServerSpec}: the scroll hook takes it from its caller so the group engine and the flat engine share one spec. */
export type ServerSpecState = ReturnType<typeof useServerSpec>;

const specOf = (seed?: Partial<ServerSpec>, groups = false): ServerSpec => ({
  sorts: [...(seed?.sorts ?? EMPTY_SPEC.sorts)],
  filters: [...(seed?.filters ?? EMPTY_SPEC.filters)],
  ...(seed?.filterJoin === "or" ? { filterJoin: "or" as const } : null),
  searchText: seed?.searchText ?? EMPTY_SPEC.searchText,
  ...(groups && seed?.groupBy?.length ? { groupBy: [...seed.groupBy] } : null),
  ...(groups && seed?.aggregates?.length ? { aggregates: [...seed.aggregates] } : null),
});

type RevalidationInput = {
  /** The `revalidateIntervalMs` option as the consumer passed it. */
  interval: unknown;
  /** Runs the refresh when a tick is due. */
  onTick: () => void;
  /** A request is in flight: a due tick waits until this turns false and then runs once. */
  busy: boolean;
  /** `false` skips the tick and waits for the next one. */
  canTick?: () => boolean;
  /** A change restarts the clock. */
  resetKey: string;
};

/**
 * Runs `onTick` every `interval` ms while the page is visible. The clock chains `setTimeout`, so ticks never stack, and
 * `restart` (called by every refresh) pushes the next tick a full interval away. Returns `restart`.
 */
export function useRevalidation({ interval: raw, onTick, busy, canTick, resetKey }: RevalidationInput) {
  const { interval, invalid, raised } = readRevalidateInterval(raw);
  const live = useRef({ interval, onTick, busy, canTick });
  useLayoutEffect(() => {
    live.current = { interval, onTick, busy, canTick };
  });
  const clock = useRef<{ timer: ReturnType<typeof setTimeout> | null; deadline: number; waiting: boolean; warned: boolean; warnedRaised: boolean }>({ timer: null, deadline: 0, waiting: false, warned: false, warnedRaised: false });

  const fireRef = useRef<() => void>(() => {});
  const arm = useCallback(() => {
    const state = clock.current;
    if (state.timer !== null) clearTimeout(state.timer);
    state.timer = null;
    const { interval: ms } = live.current;
    if (ms === null || typeof document === "undefined" || document.visibilityState === "hidden") return;
    state.timer = setTimeout(() => {
      state.timer = null;
      fireRef.current();
    }, Math.max(0, state.deadline - Date.now()));
  }, []);

  const restart = useCallback(() => {
    clock.current.deadline = Date.now() + (live.current.interval ?? 0);
    clock.current.waiting = false;
    arm();
  }, [arm]);

  const fire = useCallback(() => {
    if (live.current.busy) {
      clock.current.waiting = true;
      return;
    }
    if (!live.current.canTick || live.current.canTick()) live.current.onTick();
    restart();
  }, [restart]);
  useLayoutEffect(() => {
    fireRef.current = fire;
  }, [fire]);

  useEffect(() => {
    if (invalid && isDev() && !clock.current.warned) {
      clock.current.warned = true;
      console.warn("[data-grid-server] revalidateIntervalMs must be a number of milliseconds above 0, so revalidation is off");
    }
  }, [invalid]);

  useEffect(() => {
    if (raised && isDev() && !clock.current.warnedRaised) {
      clock.current.warnedRaised = true;
      console.warn(`[data-grid-server] revalidateIntervalMs below ${MIN_REVALIDATE_INTERVAL} ms is raised to ${MIN_REVALIDATE_INTERVAL} ms`);
    }
  }, [raised]);

  useEffect(() => {
    if (interval === null || typeof document === "undefined") return;
    restart();
    const onVisibility = () => {
      if (document.visibilityState === "hidden") {
        if (clock.current.timer !== null) clearTimeout(clock.current.timer);
        clock.current.timer = null;
      } else if (Date.now() >= clock.current.deadline) fire();
      else arm();
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      if (clock.current.timer !== null) clearTimeout(clock.current.timer);
      clock.current.timer = null;
    };
    // `resetKey` restarts the clock.
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [interval, resetKey, restart, arm, fire]);

  useEffect(() => {
    if (!busy && clock.current.waiting) {
      clock.current.waiting = false;
      // A hidden page leaves the due tick to the visibility handler.
      if (typeof document !== "undefined" && document.visibilityState !== "hidden") fire();
    }
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [busy]);

  return restart;
}

type ReshapeInput = {
  /** The `reshapeDelayMs` option as the consumer passed it. */
  delay: unknown;
  /** The spec has a sort or a filter, so a pushed row can belong elsewhere: `delay` defaults to {@link DEFAULT_RESHAPE_DELAY}. */
  ordered: boolean;
  /** Runs the refresh when a reshape is due. */
  run: () => void;
  /** A request is in flight: a due reshape waits until this turns false and then runs once. */
  busy: boolean;
  /** `false` drops a due reshape. */
  canRun?: () => boolean;
  /** A change cancels the pending reshape: the request it starts fetches the rows anyway. */
  resetKey: string;
  warn: (kind: string, message: string) => void;
};

/** `"stale"` comes from a deferred push, `"soon"` from a stream delete or `reshape()`, `"urgent"` from `reconcileView()` or an immediate push. */
export type ReshapeTrigger = "stale" | "soon" | "urgent";

/**
 * Schedules the refresh that places pushed rows again. With `reshapeDelayMs`, `"stale"` and `"soon"` triggers start or join one
 * timer, so a steady feed reshapes at most once per delay; without it `"stale"` triggers do nothing and `"soon"` runs on the next
 * frame. `"urgent"` always runs on the next frame. A reshape that falls due during a request or while the page is hidden waits and runs once.
 */
export function useReshape({ delay: raw, ordered, run, busy, canRun, resetKey, warn }: ReshapeInput) {
  const { delay, invalid, raised } = readReshapeDelay(raw);
  const staleDelay = delay ?? (raw === undefined && ordered ? DEFAULT_RESHAPE_DELAY : null);
  const live = useRef({ delay, staleDelay, run, busy, canRun, warn });
  useLayoutEffect(() => {
    live.current = { delay, staleDelay, run, busy, canRun, warn };
  });
  const pending = useRef<{ timer: ReturnType<typeof setTimeout> | null; cancelFrame: (() => void) | null; waiting: boolean }>({ timer: null, cancelFrame: null, waiting: false });

  const cancel = useCallback(() => {
    const state = pending.current;
    if (state.timer !== null) clearTimeout(state.timer);
    state.cancelFrame?.();
    state.timer = null;
    state.cancelFrame = null;
    state.waiting = false;
  }, []);

  const due = useCallback(() => {
    const state = pending.current;
    if (live.current.busy || (typeof document !== "undefined" && document.visibilityState === "hidden")) {
      state.waiting = true;
      return;
    }
    state.waiting = false;
    if (!live.current.canRun || live.current.canRun()) live.current.run();
  }, []);

  const request = useCallback(
    (trigger: ReshapeTrigger) => {
      const state = pending.current;
      const ms = trigger === "stale" ? live.current.staleDelay : live.current.delay;
      if (trigger === "stale" || (trigger === "soon" && ms !== null)) {
        if (ms === null || state.timer !== null) return;
        state.timer = setTimeout(() => {
          state.timer = null;
          due();
        }, ms);
        return;
      }
      if (state.cancelFrame !== null) return;
      state.cancelFrame = scheduleFrame(() => {
        state.cancelFrame = null;
        due();
      });
    },
    [due],
  );

  useEffect(() => {
    if (invalid) live.current.warn("reshapeDelayMs", "reshapeDelayMs must be a number of milliseconds above 0, so the reshape delay is off");
    else if (raised) live.current.warn("reshapeDelayMs", `reshapeDelayMs below ${MIN_RESHAPE_DELAY} ms is raised to ${MIN_RESHAPE_DELAY} ms`);
  }, [invalid, raised]);

  useEffect(() => {
    const onVisibility = () => {
      if (document.visibilityState !== "hidden" && pending.current.waiting) due();
    };
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      cancel();
    };
  }, [due, cancel]);

  useEffect(() => {
    cancel();
  }, [resetKey, cancel]);

  useEffect(() => {
    if (!busy && pending.current.waiting) due();
    // oxlint-disable-next-line react-hooks/exhaustive-deps
  }, [busy]);

  return { request, cancel };
}

type WiringSave = Parameters<typeof registerServerWiring>[1]["wrapSave"];

/** Registers during render, not in `useMemo`: the React Compiler drops a memo whose result is unused. */
export function useRegisteredWiring(props: { data: readonly unknown[] }, wrapSave: unknown) {
  registerServerWiring(props.data, { props, wrapSave: wrapSave as WiringSave });
}

